mkdir -p src/lang test scripts && cat > package.json <<'EOF'
{
  "name": "logomocja",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "bun run scripts/build.ts",
    "test": "bun test",
    "dev": "bun run scripts/dev.ts"
  }
}
EOF
cat > tsconfig.json <<'EOF'
{ "compilerOptions": { "target": "ES2022", "module": "ESNext", "moduleResolution": "bundler", "strict": true, "lib": ["ES2022","DOM","DOM.Iterable"], "noEmit": true, "skipLibCheck": true, "types": [] } }
EOF
printf 'node_modules\ndist\n' > .gitignore
cat > test/interpreter.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

const seg = (from: number[], to: number[], color = "#16866a", width = 3) => ({ from, to, color, width });

describe("turtle basics", () => {
  test("np moves along +Y from the origin with the default pen", () => {
    const r = run("np 100", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toEqual([seg([0, 0, 0], [0, 100, 0])]);
  });
});
EOF
bun test 2>&1 | tail -8

