export type Mode = "2d" | "3d";
export type Vec = [number, number, number];

export interface Segment {
  from: Vec;
  to: Vec;
  color: string;
  width: number;
}

export interface LangError {
  message: string;
  line: number;
  column: number;
}

export interface RunResult {
  segments: Segment[];
  error: LangError | null;
}

export interface Pos {
  line: number;
  column: number;
}

export class LangFailure extends Error {
  constructor(
    message: string,
    public line: number,
    public column: number,
  ) {
    super(message);
  }
  toError(): LangError {
    return { message: this.message, line: this.line, column: this.column };
  }
}

export const LIMITS = {
  sourceChars: 50_000,
  tokens: 10_000,
  nesting: 32,
  frames: 32,
  ops: 10_000,
  segments: 10_000,
  coord: 100_000,
  repeat: 10_000,
};
EOF
cat > lexer.ts <<'EOF'
import { LIMITS, LangFailure } from "./types";

export type TokKind = "num" | "word" | "colon" | "str" | "op" | "cmp" | "lbr" | "rbr" | "lpar" | "rpar" | "comma" | "ma";

export interface Token {
  kind: TokKind;
  /** normalised text: lower-cased and NFC for words */
  text: string;
  value: number;
  line: number;
  column: number;
  spaceBefore: boolean;
  spaceAfter: boolean;
  firstOnLine: boolean;
  lastOnLine: boolean;
}

const isLetter = (c: string) => /[\p{L}_]/u.test(c);
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);
const isDigit = (c: string) => c >= "0" && c <= "9";

export function lex(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let lineStart = 0;
  let sawSpace = true;
  let firstOnLine = true;

  const fail = (msg: string, at: number): never => {
    throw new LangFailure(msg, line, at - lineStart + 1);
  };
  const push = (kind: TokKind, text: string, start: number, value = 0) => {
    if (tokens.length >= LIMITS.tokens) {
      throw new LangFailure(`Przekroczono limit ${LIMITS.tokens} tokenów.`, line, start - lineStart + 1);
    }
    tokens.push({
      kind, text, value, line, column: start - lineStart + 1,
      spaceBefore: sawSpace, spaceAfter: false, firstOnLine, lastOnLine: false,
    });
    firstOnLine = false;
    sawSpace = false;
  };
  const markSpaceAfter = () => {
    const t = tokens[tokens.length - 1];
    if (t) t.spaceAfter = true;
  };
  const endLine = () => {
    const t = tokens[tokens.length - 1];
    if (t && t.line === line) t.lastOnLine = true;
  };

  while (i < source.length) {
    if (i === LIMITS.sourceChars) {
      throw new LangFailure(`Program jest za długi (limit ${LIMITS.sourceChars} znaków).`, line, i - lineStart + 1);
    }
    const c = source[i];
    if (c === "\n" || c === "\r") {
      endLine();
      if (c === "\r" && source[i + 1] === "\n") i++;
      i++;
      line++;
      lineStart = i;
      firstOnLine = true;
      sawSpace = true;
      markSpaceAfter();
      continue;
    }
    if (c === " " || c === "\t" || c === "\f" || c === "\v" || c === " " || c === "﻿") {
      sawSpace = true;
      markSpaceAfter();
      i++;
      continue;
    }
    if (c === ";") {
      while (i < source.length && source[i] !== "\n" && source[i] !== "\r") i++;
      sawSpace = true;
      markSpaceAfter();
      continue;
    }
    const start = i;
    if (isDigit(c) || (c === "." && isDigit(source[i + 1] ?? ""))) {
      while (isDigit(source[i] ?? "")) i++;
      if (source[i] === "." && isDigit(source[i + 1] ?? "")) {
        i++;
        while (isDigit(source[i] ?? "")) i++;
      }
      const next = source[i] ?? "";
      if (next === "." || isWordChar(next)) {
        while (i < source.length && (isWordChar(source[i]) || source[i] === ".")) i++;
        fail(`Nieprawidłowa liczba „${source.slice(start, i)}”. Liczby zapisujemy jako 12, 12.5 lub .5.`, start);
      }
      const text = source.slice(start, i);
      const value = Number(text);
      if (!Number.isFinite(value)) fail("Liczba jest poza dozwolonym zakresem.", start);
      push("num", text, start, value);
      continue;
    }
    if (isLetter(c)) {
      while (i < source.length && isWordChar(source[i])) i++;
      const text = source.slice(start, i).normalize("NFC").toLowerCase();
      if (text === "ma" && source[i] === ":") {
        i++;
        push("ma", "ma:", start);
      } else push("word", text, start);
      continue;
    }
    if (c === ":") {
      i++;
      if (!isLetter(source[i] ?? "")) fail("Po dwukropku oczekiwano nazwy, np. :bok.", start);
      const ns = i;
      while (i < source.length && isWordChar(source[i])) i++;
      push("colon", source.slice(ns, i).normalize("NFC").toLowerCase(), start);
      continue;
    }
    if (c === '"') {
      i++;
      while (i < source.length && source[i] !== '"' && source[i] !== "\n" && source[i] !== "\r") i++;
      if (source[i] !== '"') fail("Niedomknięty napis — brakuje zamykającego cudzysłowu.", start);
      i++;
      push("str", source.slice(start + 1, i - 1), start);
      continue;
    }
    if (c === "<" || c === ">" || c === "=") {
      i++;
      if ((c === "<" && (source[i] === "=" || source[i] === ">")) || (c === ">" && source[i] === "=")) i++;
      push("cmp", source.slice(start, i), start);
      continue;
    }
    i++;
    switch (c) {
      case "+": case "-": case "*": case "/": push("op", c, start); break;
      case "[": push("lbr", c, start); break;
      case "]": push("rbr", c, start); break;
      case "(": push("lpar", c, start); break;
      case ")": push("rpar", c, start); break;
      case ",": push("comma", c, start); break;
      default: fail(`Nieznany znak „${c}”.`, start);
    }
  }
  endLine();
  markSpaceAfter();
  return tokens;
}
EOF

