import type { Expr, Program, Stmt } from "./ast";
import { LangFailure, LIMITS, type LangError, type Pos, type Segment, type Vec } from "./types";

const norm = (v: number) => v + 0;

function evalExpr(e: Expr): number {
  return (e.rpn[0] as { v: number }).v;
}

export class Machine {
  segments: Segment[] = [];
  pos: Vec = [0, 0, 0];
  h: Vec = [0, 1, 0];
  r: Vec = [1, 0, 0];
  u: Vec = [0, 0, 1];
  penDown = true;
  color = "#16866a";
  width = 3;
  ops = 0;
  pending: Pos | null = null;
  done = false;
  error: LangError | null = null;
  private gen: Generator<Pos, void, void>;

  constructor(private program: Program) {
    this.gen = this.main();
    this.advance();
  }

  /** Executes the pending operation and runs up to the next one. */
  step(): void {
    if (!this.done) this.advance();
  }

  private advance() {
    try {
      const r = this.gen.next();
      if (r.done) {
        this.done = true;
        this.pending = null;
      } else this.pending = r.value;
    } catch (e) {
      if (!(e instanceof LangFailure)) throw e;
      this.done = true;
      this.pending = null;
      this.error = e.toError();
    }
  }

  private *main(): Generator<Pos, void, void> {
    for (const s of this.program.body) {
      yield* this.exec(s);
    }
  }

  private *exec(s: Stmt): Generator<Pos, void, void> {
    this.ops++;
    yield s.tok;
    switch (s.kind) {
      case "move": this.moveBy(s.sign * evalExpr(s.arg), s.tok); break;
      case "turn": this.turn(s.axis, s.sign * evalExpr(s.arg)); break;
      case "pen": this.penDown = s.down; break;
      case "color": this.color = s.value; break;
      case "width": this.width = evalExpr(s.arg); break;
    }
  }

  private moveBy(d: number, at: Pos) {
    const to: Vec = [norm(this.pos[0] + this.h[0] * d), norm(this.pos[1] + this.h[1] * d), norm(this.pos[2] + this.h[2] * d)];
    if (this.penDown && (to[0] !== this.pos[0] || to[1] !== this.pos[1] || to[2] !== this.pos[2])) {
      this.segments.push({ from: this.pos, to, color: this.color, width: this.width });
    }
    this.pos = to;
  }

  private turn(axis: string, deg: number) {
    const a = (deg * Math.PI) / 180;
    const c = Math.cos(a), s = Math.sin(a);
    if (axis === "yaw") {
      const h = this.h, r = this.r;
      this.h = [h[0] * c + r[0] * s, h[1] * c + r[1] * s, h[2] * c + r[2] * s];
      this.r = [r[0] * c - h[0] * s, r[1] * c - h[1] * s, r[2] * c - h[2] * s];
    }
  }
}
