describe("flat commands", () => {
  test("pw 90 turns the heading to +X (clockwise seen from above)", () => {
    expect(run("pw 90 np 50", "2d").segments).toEqual([seg([0, 0, 0], [50, 0, 0])]);
  });
  test("lw 90 turns the heading to -X", () => {
    expect(run("lw 90 np 50", "2d").segments).toEqual([seg([0, 0, 0], [-50, 0, 0])]);
  });
  test("ws moves backwards", () => {
    expect(run("ws 30", "2d").segments).toEqual([seg([0, 0, 0], [0, -30, 0])]);
  });
  test("a raised pen moves without drawing, a lowered pen draws again", () => {
    const r = run("pod np 10 opu np 5", "2d");
    expect(r.segments).toEqual([seg([0, 10, 0], [0, 15, 0])]);
  });
  test("kolor and grubosc apply to later segments only, colour is lower-cased", () => {
    const r = run('np 1 kolor "#C1763D" grubosc 7 np 1', "2d");
    expect(r.segments.map((s) => [s.color, s.width])).toEqual([["#16866a", 3], ["#c1763d", 7]]);
  });
  test("English, accented and upper-case spellings are equivalent", () => {
    const a = run("FD 10 RT 90 Forward 10 left 90 NAPRZÓD 5", "2d");
    const b = run("np 10 pw 90 np 10 lw 90 np 5", "2d");
    expect(a.error).toBeNull();
    expect(a.segments).toEqual(b.segments);
    expect(a.segments).toHaveLength(3);
  });
  test("comments run to the end of the line", () => {
    expect(run("; nic\nnp 10 ; ruch\n;np 99", "2d").segments).toHaveLength(1);
  });
  test("a zero move draws nothing", () => {
    expect(run("np 0 ws 0", "2d").segments).toEqual([]);
  });
  test("quarter turns give exact coordinates", () => {
    const r = run("np 120 pw 90 np 120 pw 90 np 120 pw 90 np 120", "2d");
    expect(r.segments.map((s) => s.to)).toEqual([[0, 120, 0], [120, 120, 0], [120, 0, 0], [0, 0, 0]]);
  });
