    expect(endY("np -(3 - 5)")).toBe(2);
    expect(endY("np - -2")).toBe(2);
    expect(endY("np +-+3")).toBe(-3);
    expect(endY("np 5 - -2")).toBe(7);
    expect(endY("np 5*-2")).toBe(-10);
