new='''  /** Parses a full expression; `cmd` is the command that wants it (used for "missing argument" reports). */
  private parseExpr(cmd: Token): Expr {
    const first = this.peek();
    const rpn: RpnOp[] = [];
    this.sum(rpn, cmd, `Polecenie „${cmd.text}” wymaga argumentu.`);
    return {
      rpn,
      pos: { line: first!.line, column: first!.column },
      constant: rpn.every((o) => o.k === "num" || o.k === "neg" || o.k === "bin"),
    };
  }

  private isBinary(t: Token | undefined, ops: string): t is Token {
    return !!t && t.kind === "op" && ops.includes(t.text) && t.spaceBefore === t.spaceAfter;
  }

  private sum(out: RpnOp[], ctx: Token, missing: string) {
    this.term(out, ctx, missing);
    for (let t = this.peek(); this.isBinary(t, "+-"); t = this.peek()) {
      this.i++;
      this.term(out, t, `Brakuje wartości po „${t.text}”.`);
      out.push({ k: "bin", op: t.text as "+" | "-" });
    }
  }

  private term(out: RpnOp[], ctx: Token, missing: string) {
    this.unary(out, ctx, missing);
    for (let t = this.peek(); this.isBinary(t, "*/"); t = this.peek()) {
      this.i++;
      this.unary(out, t, `Brakuje wartości po „${t.text}”.`);
      out.push({ k: "bin", op: t.text as "*" | "/" });
    }
  }

  private unary(out: RpnOp[], ctx: Token, missing: string) {
    let negs = 0;
    let last = ctx;
    for (let t = this.peek(); t && t.kind === "op" && (t.text === "-" || t.text === "+"); t = this.peek()) {
      if (t.text === "-") negs++;
      last = t;
      this.i++;
    }
    this.atom(out, last, missing);
    if (negs % 2 === 1) out.push({ k: "neg" });
  }

  private atom(out: RpnOp[], ctx: Token, missing: string) {
    const t = this.peek();
    if (!t) this.fail(missing, ctx);
    switch (t!.kind) {
      case "num":
        this.i++;
        out.push({ k: "num", v: t!.value });
        return;
      case "lpar": {
        this.i++;
        this.sum(out, t!, "Brakuje wyrażenia w nawiasie.");
        const close = this.peek();
        if (!close || close.kind !== "rpar") this.fail("Brakuje zamykającego nawiasu „)”.", t!);
        this.i++;
        return;
      }
    }
    this.fail(missing, t!);
  }
}

