    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("a literal repeat count out of range or non-integer is a parse-time error at the argument", () => {
    for (const [src, col] of [["np 1\npowtorz 2.5 [np 1]", 9], ["powtorz 10001 [np 1]", 9], ["powtorz -1 [np 1]", 9], ["powtorz 6 / 4 [np 1]", 9]] as const) {
      const r = run(src, "2d");
      expect(r.segments, src).toEqual([]);
      expect(r.error?.column, src).toBe(col);
    }
  });
  test("a literal width out of 1-12 or non-integer is a parse-time error at the argument", () => {
    for (const src of ["np 1 grubosc 0", "grubosc 13", "grubosc 2.5"]) {
