describe("variables", () => {
  test("niech assigns and later niech reassigns", () => {
    expect(run("niech x 5 np x niech x x * 2 np x", "2d").segments.map((s) => s.to[1])).toEqual([5, 15]);
  });
  test("names ignore case and accept the :name form", () => {
    expect(run("NIECH Bok 7 np :bok np BOK", "2d").segments.map((s) => s.to[1])).toEqual([7, 14]);
  });
  test("a variable can negate itself", () => {
    expect(run("niech z 1 powtorz 3 [niech z -z np z]", "2d").segments.map((s) => s.to[1])).toEqual([-1, 0, -1]);
  });
  test("a name that is never assigned is a parse-time error at the name; nothing is drawn", () => {
    const r = run("np 10\nnp abc", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("a variable assigned later at top level is declared; reading it early is a run-time error at the argument", () => {
    const r = run("np 10\nnp 3 + x\nniech x 4", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("variable names may not be command words", () => {
    expect(run("niech np 5", "2d").error).toMatchObject({ line: 1, column: 7 });
    expect(run("niech nrpowt 5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("niech without a value is a missing-argument error", () => {
    expect(run("niech x", "2d").error).toMatchObject({ line: 1, column: 1 });
  });
  test("a bad width computed from a variable is a run-time error that keeps earlier strokes", () => {
    const r = run("np 5 niech w 20 grubosc w np 5", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 1, column: 25 });
  });
  test("a bad repeat count computed from a variable is a run-time error", () => {
    const r = run("np 5 niech n 1.5 powtorz n [np 1]", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 1, column: 26 });
  });
});

describe("conditionals", () => {
  const ys = (src: string) => run(src, "2d").segments.map((s) => s.to[1]);
  test("jeśli runs the body only when the condition holds", () => {
    expect(ys("jeśli 1 < 2 [np 1] jesli 2 < 1 [np 5] if 1 = 1 [np 10]")).toEqual([1, 11]);
  });
  test("all six comparisons", () => {
    const t = (c: string) => ys(`jeśli ${c} [np 1]`).length === 1;
    expect([t("2 > 1"), t("1 < 2"), t("2 = 2"), t("2 <= 2"), t("2 >= 3"), t("2 <> 3"), t("2 <> 2"), t("3<=2")])
      .toEqual([true, true, true, true, false, true, false, false]);
  });
  test("comparisons are exact", () => {
    expect(ys("jeśli 0.1 + 0.2 = 0.3 [np 1]")).toEqual([]);
  });
  test("jeżeli runs the first body or else the second", () => {
    expect(ys("jeżeli 1 > 2 [np 1] [np 2]")).toEqual([2]);
    expect(ys("jezeli 3 > 2 [np 1] [np 2]")).toEqual([1]);
    expect(ys("ifelse 3 > 2 [np 1] [np 2]")).toEqual([1]);
  });
  test("niech inside a body at top level assigns the global", () => {
    expect(ys("niech a 1 jeśli a = 1 [niech a 5] np a")).toEqual([5]);
  });
  test("a missing comparison or body is reported where it should be", () => {
    expect(run("jeśli 1 [np 1]", "2d").error).toMatchObject({ line: 1, column: 9 });
    expect(run("jeśli 1 < 2 np 1", "2d").error).toMatchObject({ line: 1, column: 13 });
    expect(run("jeżeli 1 < 2 [np 1]", "2d").error).toMatchObject({ line: 1, column: 1 });
  });
  test("an unassigned variable in a condition is reported at the operand that holds it", () => {
    const r = run("jeśli 1 < q [np 1]\nniech q 2", "2d");
    expect(r.error).toMatchObject({ line: 1, column: 11 });
  });
});
