cat >> test/interpreter.test.ts <<'EOF'

describe("procedures", () => {
  const ys = (src: string) => run(src, "2d").segments.map((s) => s.to[1]);
  test("definition with ma: and comma-separated parameters, called with expression arguments", () => {
    const src = "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n\nkwadrat 40 * 2 90";
    const r = run(src, "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([[0, 80, 0], [80, 80, 0], [80, 0, 0], [0, 0, 0]]);
  });
  test("legacy header and :name references", () => {
    const r = run("to kw :bok :kat\n powtorz 4 [np :bok pw kat]\nend\nKW 10 90", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toHaveLength(4);
  });
  test("procedures may be defined after their calls", () => {
    expect(ys("a 5\noto a ma: n\n np n\nużż".replace("użż", "już"))).toEqual([5]);
  });
  test("a parameter may share the name of a procedure: command position calls, argument position reads", () => {
    expect(ys("oto kw ma: kw\n np kw\njuż\nkw 10 kw 4")).toEqual([10, 14]);
  });
  test("a procedure without parameters", () => {
    expect(ys("oto krok\n np 3\njuż\nkrok krok")).toEqual([3, 6]);
  });
  test("recursion with stop", () => {
    expect(ys("oto a ma: n\n jeśli n < 1 [stop]\n np n\n a n - 1\njuż\na 3")).toEqual([3, 5, 6]);
  });
  test("stop inside a repeat ends the whole procedure call, not only the loop", () => {
    expect(ys("oto a\n powtorz 5 [np 1 jeśli nrpowt = 2 [stop]]\n np 100\njuż\na np 7")).toEqual([1, 2, 9]);
  });
  test("stop at top level ends the program, even inside a repeat", () => {
    expect(ys("np 1 powtorz 5 [np 1 stop] np 50")).toEqual([1, 2]);
  });
  test("niech inside a procedure is local to the call and shadows a global", () => {
    const src = "niech x 100\noto a\n niech x 1\n np x\njuż\na np x";
    expect(ys(src)).toEqual([1, 101]);
  });
  test("a procedure reads globals, and a parameter can be reassigned", () => {
    expect(ys("niech g 7\noto a ma: p\n niech p p + g\n np p\njuż\na 1")).toEqual([8]);
  });
  test("locals do not leak between calls", () => {
    const r = run("oto a\n np loc\n niech loc 5\njuż\noto b\n niech loc 3\n np loc\njuż\nb a", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([3]);
    expect(r.error).toMatchObject({ line: 2, column: 7 });
  });
  test("wrong argument count: too few is reported at the next token, too many at the extra value", () => {
    const def = "oto k ma: a, b\n np a\njuż\n";
    expect(run(def + "k 1", "2d").error).toMatchObject({ line: 4, column: 1 });
    expect(run(def + "k 1 np 5", "2d").error).toMatchObject({ line: 4, column: 5 });
    expect(run(def + "k 1 2 3", "2d").error).toMatchObject({ line: 4, column: 7 });
  });
  test("a definition inside a body or another procedure is an error at oto", () => {
    expect(run("powtorz 2 [\noto a\n np 1\njuż\n]", "2d").error).toMatchObject({ line: 2, column: 1 });
    expect(run("oto a\noto b\njuż\njuż", "2d").error).toMatchObject({ line: 2, column: 1 });
  });
  test("a missing już is reported at the oto", () => {
    expect(run("np 1\noto a\n np 1", "2d").error).toMatchObject({ line: 2, column: 1 });
  });
  test("już must stand alone on its line; a stray już is an error", () => {
    expect(run("oto a\n np 1 już", "2d").error).toMatchObject({ line: 2, column: 7 });
    expect(run("np 1\njuż", "2d").error).toMatchObject({ line: 2, column: 1 });
  });
  test("a procedure can be defined only once", () => {
    expect(run("oto a\njuż\noto A\njuż", "2d").error).toMatchObject({ line: 3, column: 5 });
  });
  test("names unknown inside a procedure are parse-time errors, even when a variable exists elsewhere", () => {
    expect(run("oto a\n niech loc 1\njuż\noto b\n np loc\njuż", "2d").error).toMatchObject({ line: 5, column: 5 });
    expect(run("oto a\n np zzz\njuż", "2d").error).toMatchObject({ line: 2, column: 5 });
  });
  test("nrpowt in a procedure body outside a repeat is a parse-time error, even if called from a repeat", () => {
    const r = run("oto a\n np nrpowt\njuż\npowtorz 3 [a]", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 5 });
  });
  test("nrpowt inside a repeat in a procedure is fine", () => {
    expect(ys("oto a\n powtorz 2 [np nrpowt]\njuż\na")).toEqual([1, 3]);
  });
  test("procedure names cannot be variable names, command words cannot be procedure names", () => {
    expect(run("oto a\njuż\nniech a 1", "2d").error).toMatchObject({ line: 3, column: 7 });
    expect(run("oto np\njuż", "2d").error).toMatchObject({ line: 1, column: 5 });
  });
  test("unknown commands are errors at the word", () => {
    expect(run("np 1\nfoo 2", "2d").error).toMatchObject({ line: 2, column: 1 });
  });
  test("recursion deeper than 32 active frames is a run-time error and keeps what was drawn", () => {
    const r = run("oto a ma: n\n np 1\n a n + 1\njuż\na 1", "2d");
    expect(r.segments).toHaveLength(32);
    expect(r.error).toMatchObject({ line: 3, column: 2 });
  });
});
