describe("3D orientation", () => {
  const end = (src: string) => {
    const r = run(src, "3d");
    expect(r.error).toBeNull();
    return r.segments[r.segments.length - 1].to;
  };
  test("gora pitches the nose up, dol down", () => {
    expect(end("gora 90 np 10")).toEqual([0, 0, 10]);
    expect(end("dol 90 np 10")).toEqual([0, 0, -10]);
    expect(end("pitchup 90 fd 10")).toEqual([0, 0, 10]);
  });
  test("after gora 90 the right vector is unchanged: pw 90 heads along +X", () => {
    expect(end("gora 90 pw 90 np 10")).toEqual([10, 0, 0]);
  });
  test("pp 90 makes the turtle's up its former right and its right its former down", () => {
    expect(end("pp 90 pw 90 np 10")).toEqual([0, 0, -10]);
    expect(end("rr 90 gora 90 np 10")).toEqual([10, 0, 0]);
  });
  test("pl rolls the other way", () => {
    expect(end("pl 90 pw 90 np 10")).toEqual([0, 0, 10]);
    expect(end("przechyllewo 90 gora 90 np 10")).toEqual([-10, 0, 0]);
  });
  test("rolling does not change the heading", () => {
    expect(end("pp 37 pl 120 rl 5 np 10")).toEqual([0, 10, 0]);
  });
  test("a tilted circle (pierścień-style) closes on itself", () => {
    const r = run("gora 30 powtorz 36 [np 12 pw 10]", "3d");
    const last = r.segments[35].to;
    expect(Math.hypot(...last)).toBeLessThan(1e-9);
  });
  test("pitch and roll are parse-time errors in 2D, at the command", () => {
    for (const c of ["gora", "dol", "pp", "pl", "pitchup", "rl"]) {
      const r = run(`np 5\n  ${c} 10`, "2d");
      expect(r.segments, c).toEqual([]);
      expect(r.error, c).toMatchObject({ line: 2, column: 3 });
    }
  });
  test("flat programs give identical coordinates in both modes", () => {
    const src = "powtorz 12 [powtorz 4 [np 100 pw 90] pw 30] pod lw 17.5 np 33 opu kolor \"#a478c0\" np 20";
    expect(run(src, "3d")).toEqual(run(src, "2d"));
  });
});

describe("dom and czyść", () => {
  test("dom draws a segment back to the origin when the pen is down and restores the orientation", () => {
    const r = run("np 10 pw 90 np 10 dom np 5", "2d");
    expect(r.segments.map((s) => [s.from, s.to])).toEqual([
      [[0, 0, 0], [0, 10, 0]], [[0, 10, 0], [10, 10, 0]], [[10, 10, 0], [0, 0, 0]], [[0, 0, 0], [0, 5, 0]],
    ]);
  });
  test("dom with the pen up draws nothing and keeps pen, colour and width", () => {
    const r = run('kolor "#2b6fb3" grubosc 5 pod np 10 dom opu np 1', "2d");
    expect(r.segments).toEqual([seg([0, 0, 0], [0, 1, 0], "#2b6fb3", 5)]);
  });
  test("dom at the origin draws nothing", () => expect(run("dom", "2d").segments).toEqual([]));
  test("dom resets the 3D orientation", () => {
    const r = run("gora 90 pp 45 dom np 10", "3d");
    expect(r.segments.at(-1)!.to).toEqual([0, 10, 0]);
  });
  test("czyść forgets segments but not the turtle", () => {
    const r = run("np 1 czyść np 2\ncs np 3 clearscreen", "2d");
    expect(r.segments).toEqual([]);
    const r2 = run("np 1 czysc np 2", "2d");
    expect(r2.segments).toEqual([seg([0, 1, 0], [0, 3, 0])]);
  });
  test("after a run-time error only segments after the last czyść remain", () => {
    const r = run("np 1 czyść np 2 np 1 / 0", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).not.toBeNull();
  });
});
