describe("limits", () => {
  test("source up to 50,000 characters is accepted, one more is an error at that character", () => {
    expect(run(" ".repeat(50_000), "2d").error).toBeNull();
    expect(run(";".repeat(50_001), "2d").error).toMatchObject({ line: 1, column: 50_001 });
    expect(run("np 1\n" + ";".repeat(49_996) + "x", "2d").error).toMatchObject({ line: 2, column: 49_997 });
  });
  test("10,000 tokens are accepted, the 10,001st is an error", () => {
    expect(run("pod ".repeat(10_000), "2d").error).not.toBeNull(); // ops limit, not tokens
    expect(run("pod ".repeat(10_000), "2d").error!.message).toContain("operacji");
    const r = run("pod\n".repeat(10_001), "2d");
    expect(r.error).toMatchObject({ line: 10_001, column: 1 });
    expect(r.error!.message).toContain("token");
  });
  test("10,000 executed operations are allowed, the 10,001st is an error (repeat iterations count)", () => {
    expect(run("powtorz 3333 [pod pod]", "2d").error).toBeNull();
    expect(run("powtorz 3334 [pod pod]", "2d").error).not.toBeNull();
    expect(run("powtorz 9999 []", "2d").error).toBeNull();
    expect(run("powtorz 10000 []", "2d").error).not.toBeNull();
  });
  test("conditional bodies and calls count their finishing step", () => {
    expect(run("powtorz 2499 [jeśli 1 = 1 [pod]]", "2d").error).toBeNull();
    expect(run("powtorz 2500 [jeśli 1 = 1 [pod]]", "2d").error).not.toBeNull();
    const def = "oto a\n pod\njuż\n";
    expect(run(def + "powtorz 2499 [a]", "2d").error).toBeNull();
    expect(run(def + "powtorz 2500 [a]", "2d").error).not.toBeNull();
  });
  test("an operations-limit error keeps what was drawn", () => {
    const r = run("np 1 powtorz 5000 [pod pod]", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).not.toBeNull();
  });
  test("32 nested repeats are fine, repeat frames inside procedure calls count too", () => {
    expect(run("powtorz 1 [".repeat(32) + "np 1" + "]".repeat(32), "2d").error).toBeNull();
    const r = run("oto a\n np 1\n powtorz 1 [a]\njuż\na", "2d");
    expect(r.segments).toHaveLength(16);
    expect(r.error).toMatchObject({ line: 3 });
  });
  test("coordinates stay within ±100,000", () => {
    expect(run("np 100000 pw 90 np 100000 pw 90 ws 200000", "2d").error).toBeNull();
    const r = run("np 100000\nnp 1", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 1 });
    expect(run("lw 90 np 100001", "2d").error).toMatchObject({ line: 1, column: 7 });
    expect(run("gora 90 np 100001", "3d").error).not.toBeNull();
  });
});
