import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";
import { EXAMPLES, exampleById } from "../src/examples";

const EXPECTED: [string, "2d" | "3d", number][] = [
  ["kwadrat", "2d", 4],
  ["gwiazda", "2d", 5],
  ["rozeta", "2d", 48],
  ["spirala", "2d", 90],
  ["wielokaty", "2d", 42],
  ["drzewo", "2d", 255],
  ["sniezynka", "2d", 768],
  ["schody", "3d", 12],
  ["szescian", "3d", 17],
  ["pierscien", "3d", 36],
  ["kula", "3d", 432],
  ["helisa", "3d", 240],
  ["drzewo3d", "3d", 121],
];

describe("standard programs", () => {
  test("exactly the thirteen programs are shipped, each with its mode", () => {
    expect(EXAMPLES.map((e) => [e.id, e.mode])).toEqual(EXPECTED.map(([id, mode]) => [id, mode]));
  });
  test("Kwadrat is shipped verbatim", () => {
    expect(exampleById("kwadrat")!.source).toBe(
      '; Cztery boki, cztery skręty.\nkolor "#16866a"\ngrubosc 3\npowtorz 4 [\n  np 120\n  pw 90\n]',
    );
  });
  for (const [id, mode, count] of EXPECTED) {
    test(`${id} runs without error in ${mode} and draws ${count} segments`, () => {
      const r = run(exampleById(id)!.source, mode);
      expect(r.error).toBeNull();
      expect(r.segments).toHaveLength(count);
    });
  }
  test("the 2D programs draw the same shapes when run in 3D mode", () => {
    for (const e of EXAMPLES.filter((e) => e.mode === "2d")) {
      expect(run(e.source, "3d"), e.id).toEqual(run(e.source, "2d"));
    }
  });
  test("Gwiazda is a closed pentagram with side 180", () => {
    const r = run(exampleById("gwiazda")!.source, "2d");
    expect(Math.hypot(...r.segments[4].to)).toBeLessThan(1e-9);
    expect(Math.hypot(r.segments[2].to[0] - r.segments[2].from[0], r.segments[2].to[1] - r.segments[2].from[1])).toBeCloseTo(180, 9);
  });
  test("Sześcian has exactly the twelve edges of a cube of side 100", () => {
    const r = run(exampleById("szescian")!.source, "3d");
    const key = (v: number[]) => v.map((c) => Math.round(c)).join(",");
    const edges = new Set(r.segments.map((s) => [key(s.from), key(s.to)].sort().join("|")));
    expect(edges.size).toBe(12);
    for (const s of r.segments) {
      expect(Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2])).toBeCloseTo(100, 9);
      for (const c of [...s.from, ...s.to]) expect(Math.min(Math.abs(c), Math.abs(c - 100))).toBeLessThan(1e-9);
    }
  });
  test("Schody climbs: the last step ends at height 6·20 and depth 6·35", () => {
    const r = run(exampleById("schody")!.source, "3d");
    const last = r.segments.at(-1)!.to;
    expect(last[0]).toBeCloseTo(0, 9);
    expect(last[1]).toBeCloseTo(210, 9);
    expect(last[2]).toBeCloseTo(120, 9);
  });
});
EOF
