mkdir -p src/exec && cat > test/controller.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { Controller } from "../src/exec/controller";

const PROG = "np 10\npw 90\nnp 20\nnp 5";

describe("execution controls", () => {
  test("a new controller is idle with an empty drawing", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    const s = c.snapshot();
    expect(s.state).toBe("idle");
    expect(s.segments).toEqual([]);
    expect(s.currentLine).toBeNull();
  });

  test("run starts without drawing; advance executes the requested number of operations", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.run();
    expect(c.snapshot().state).toBe("running");
    expect(c.snapshot().segments).toHaveLength(0);
    c.advance(1);
    expect(c.snapshot().segments).toHaveLength(1);
    c.advance(Infinity);
    expect(c.snapshot().state).toBe("finished");
    expect(c.snapshot().segments).toHaveLength(3);
  });

  test("step executes one command and reports the line of the next one", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.step();
    let s = c.snapshot();
    expect(s.state).toBe("paused");
    expect(s.segments).toHaveLength(1);
    expect(s.currentLine).toMatchObject({ line: 2 });
    c.step();
    s = c.snapshot();
    expect(s.segments).toHaveLength(1);
    expect(s.currentLine).toMatchObject({ line: 3 });
    c.step();
    c.step();
    s = c.snapshot();
    expect(s.state).toBe("finished");
    expect(s.segments).toHaveLength(3);
    expect(s.currentLine).toBeNull();
  });

  test("the turtle snapshot follows position and heading", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.step();
    c.step();
    expect(c.snapshot().turtle.pos).toEqual([0, 10, 0]);
    expect(c.snapshot().turtle.h).toEqual([1, 0, 0]);
  });

  test("pause freezes the animation and resume continues it", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.run();
    c.advance(1);
    c.pause();
    expect(c.snapshot().state).toBe("paused");
    c.advance(10);
    expect(c.snapshot().segments).toHaveLength(1);
    c.resume();
    expect(c.snapshot().state).toBe("running");
    c.advance(Infinity);
    expect(c.snapshot().segments).toHaveLength(3);
  });

  test("step while running pauses and executes one command", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.run();
    c.step();
    expect(c.snapshot().state).toBe("paused");
    expect(c.snapshot().segments).toHaveLength(1);
  });

  test("reset clears the drawing, the turtle and the error", () => {
    const c = new Controller();
    c.load("np 10 pw 90 np 1 / 0", "2d");
    c.run();
    c.advance(Infinity);
    expect(c.snapshot().state).toBe("error");
    c.reset();
    const s = c.snapshot();
    expect(s.state).toBe("idle");
    expect(s.segments).toEqual([]);
    expect(s.error).toBeNull();
    expect(s.turtle.pos).toEqual([0, 0, 0]);
  });

  test("running again restarts from scratch and gives the same drawing", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.runToEnd();
    const first = c.snapshot().segments;
    c.runToEnd();
    expect(c.snapshot().segments).toEqual(first);
    expect(first).toHaveLength(3);
  });

  test("a parse-time error draws nothing, even after earlier commands were valid", () => {
    const c = new Controller();
    c.load("np 10\nfoo", "2d");
    c.run();
    const s = c.snapshot();
    expect(s.state).toBe("error");
    expect(s.segments).toEqual([]);
    expect(s.error).toMatchObject({ line: 2, column: 1 });
  });

  test("a run-time error keeps what was drawn and stops", () => {
    const c = new Controller();
    c.load("np 10\nnp 1 / 0\nnp 5", "2d");
    c.runToEnd();
    const s = c.snapshot();
    expect(s.state).toBe("error");
    expect(s.segments).toHaveLength(1);
    expect(s.error).toMatchObject({ line: 2 });
    expect(s.currentLine).toBeNull();
  });

  test("stepping onto a run-time error stops there", () => {
    const c = new Controller();
    c.load("np 10\nnp 1 / 0", "2d");
    c.step();
    c.step();
    expect(c.snapshot().state).toBe("error");
    expect(c.snapshot().segments).toHaveLength(1);
  });

  test("editing while a program is running stops it, keeps the drawing and marks it stale", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.run();
    c.advance(1);
    c.load(PROG + "\nnp 1", "2d");
    let s = c.snapshot();
    expect(s.state).toBe("idle");
    expect(s.stale).toBe(true);
    expect(s.segments).toHaveLength(1);
    expect(s.currentLine).toBeNull();
    c.advance(100);
    expect(c.snapshot().segments).toHaveLength(1);
    c.run();
    c.advance(Infinity);
    s = c.snapshot();
    expect(s.stale).toBe(false);
    expect(s.segments).toHaveLength(4);
  });

  test("loading identical text while running does not interrupt it", () => {
    const c = new Controller();
    c.load(PROG, "2d");
    c.run();
    c.advance(1);
    c.load(PROG, "2d");
    expect(c.snapshot().state).toBe("running");
  });

  test("changing the mode resets the session", () => {
    const c = new Controller();
    c.load("np 10", "2d");
    c.runToEnd();
    c.load("np 10", "3d");
    expect(c.snapshot().state).toBe("idle");
  });

  test("3D commands run in 3D and are rejected in 2D", () => {
    const c = new Controller();
    c.load("gora 90 np 10", "3d");
    c.runToEnd();
    expect(c.snapshot().segments[0].to).toEqual([0, 0, 10]);
    c.load("gora 90 np 10", "2d");
    c.run();
    expect(c.snapshot().error?.message).toContain("3D");
  });

  test("onChange fires after every state change", () => {
    let n = 0;
    const c = new Controller(() => n++);
    c.load(PROG, "2d");
    c.step();
    c.step();
    expect(n).toBeGreaterThanOrEqual(2);
  });
});
EOF
