import { start, type LangError, type Machine, type Mode, type Pos, type Segment, type Vec } from "../lang";

export type RunState = "idle" | "running" | "paused" | "finished" | "error";

export interface Turtle {
  pos: Vec;
  h: Vec;
  r: Vec;
  u: Vec;
  penDown: boolean;
  color: string;
  width: number;
}

export interface Snapshot {
  state: RunState;
  mode: Mode;
  segments: Segment[];
  turtle: Turtle;
  /** the next command to execute while a program is active */
  currentLine: Pos | null;
  error: LangError | null;
  /** the drawing no longer corresponds to the code in the editor */
  stale: boolean;
  ops: number;
}

const INITIAL: Turtle = { pos: [0, 0, 0], h: [0, 1, 0], r: [1, 0, 0], u: [0, 0, 1], penDown: true, color: "#16866a", width: 3 };

/** Drives a program through run / step / pause / resume / reset. The caller supplies the clock via advance(). */
export class Controller {
  private source = "";
  private mode: Mode = "2d";
  private state: RunState = "idle";
  private machine: Machine | null = null;
  private error: LangError | null = null;
  private stale = false;
  private drawn = false;

  constructor(private onChange: () => void = () => {}) {}

  /** Sets the program text and mode (called on every edit). */
  load(source: string, mode: Mode): void {
    if (source === this.source && mode === this.mode) return;
    const modeChanged = mode !== this.mode;
    this.source = source;
    this.mode = mode;
    if (modeChanged) {
      this.clearSession();
    } else if (this.machine || this.drawn || this.error) {
      this.machine = null;
      this.state = "idle";
      this.error = null;
      this.stale = true;
    }
    this.onChange();
  }

  run(): void {
    this.begin("running");
  }

  /** Runs the whole program at once, without animation. */
  runToEnd(): void {
    this.begin("running");
    this.advance(Infinity);
  }

  step(): void {
    if (this.state === "idle" || this.state === "finished" || this.state === "error") this.begin("paused");
    else this.state = "paused";
    if (this.machine && this.state === "paused") this.exec(1);
    this.onChange();
  }

  pause(): void {
    if (this.state !== "running") return;
    this.state = "paused";
    this.onChange();
  }

  resume(): void {
    if (this.state !== "paused") return;
    this.state = "running";
    this.onChange();
  }

  reset(): void {
    this.clearSession();
    this.onChange();
  }

  /** Executes up to `maxOps` operations while running; returns how many were executed. */
  advance(maxOps: number): number {
    if (this.state !== "running" || !this.machine) return 0;
    const n = this.exec(maxOps);
    this.onChange();
    return n;
  }

  snapshot(): Snapshot {
    const m = this.machine;
    return {
      state: this.state,
      mode: this.mode,
      segments: m ? m.segments : [],
      turtle: m ? { pos: m.pos, h: m.h, r: m.r, u: m.u, penDown: m.penDown, color: m.color, width: m.width } : INITIAL,
      currentLine: m && !m.done ? m.pending : null,
      error: this.error,
      stale: this.stale,
      ops: m ? m.ops : 0,
    };
  }

  private clearSession() {
    this.machine = null;
    this.state = "idle";
    this.error = null;
    this.stale = false;
    this.drawn = false;
  }

  private begin(state: "running" | "paused") {
    this.stale = false;
    this.error = null;
    const { machine, error } = start(this.source, this.mode);
    this.machine = machine;
    this.drawn = !!machine;
    if (!machine) {
      this.error = error;
      this.state = "error";
    } else this.state = state;
    this.onChange();
  }

  private exec(maxOps: number): number {
    const m = this.machine!;
    let n = 0;
    while (n < maxOps && !m.done) {
      m.step();
      n++;
    }
    if (m.done) {
      this.error = m.error;
      this.state = m.error ? "error" : "finished";
    }
    return n;
  }
}
