describe("permalinks", () => {
  test("the URL carries mode and program in the hash (known literal)", () => {
    expect(encodePermalink("np 10", "2d", "https://x.pl/a/")).toBe("https://x.pl/a/#/pracownia?m=2d&p=bnAgMTA");
  });
  test("decoding returns the program and the mode", () => {
    expect(decodePermalink("#/pracownia?m=3d&p=bnAgMTA")).toEqual({ source: "np 10", mode: "3d" });
  });
  test("Polish letters, newlines and emoji survive the round trip", () => {
    const src = "; Zażółć gęślą jaźń 🐢\noto gałąź ma: dł\n  np dł\njuż\r\ngałąź 5";
    const url = encodePermalink(src, "3d", "http://localhost:3000/");
    expect(decodePermalink(url.slice(url.indexOf("#")))).toEqual({ source: src, mode: "3d" });
  });
  test("a program of the maximum size survives", () => {
    const src = "np 1 ".repeat(10_000);
    const url = encodePermalink(src, "2d", "http://h/");
    expect(decodePermalink(url.slice(url.indexOf("#")))!.source).toBe(src);
  });
  test("the hash is URL-safe", () => {
    const url = encodePermalink("???>>>~~~ ołówek", "2d", "http://h/");
    expect(url.slice(url.indexOf("#"))).toMatch(/^#\/pracownia\?m=2d&p=[A-Za-z0-9_-]+$/);
  });
  test("any base with an existing hash is replaced", () => {
    expect(encodePermalink("np 1", "2d", "http://h/p/?q=1#/wyzwania")).toStartWith("http://h/p/?q=1#/pracownia?m=2d&p=");
  });
  test("things that are not permalinks decode to null", () => {
    for (const h of ["", "#/", "#/pomoc", "#/pracownia?m=2d", "#/pracownia?m=4d&p=bnAgMTA", "#/pracownia?m=2d&p=***", "#/pracownia?m=2d&p=/w"]) {
      expect(decodePermalink(h), h).toBeNull();
    }
  });
});
