import type { Mode } from "./lang";

export interface Shared {
  source: string;
  mode: Mode;
}

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(text: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(text)) return null;
  try {
    const bin = atob(text.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** Builds a link that opens `source` in `mode`; `base` is the page URL (any existing hash is dropped). */
export function encodePermalink(source: string, mode: Mode, base: string): string {
  const page = base.split("#")[0];
  return `${page}#/pracownia?m=${mode}&p=${toBase64Url(source)}`;
}

/** Reads a permalink from a location hash; returns null when the hash is not a valid permalink. */
export function decodePermalink(hash: string): Shared | null {
  const q = hash.indexOf("?");
  if (q < 0) return null;
  const params = new URLSearchParams(hash.slice(q + 1));
  const mode = params.get("m");
  const p = params.get("p");
  if ((mode !== "2d" && mode !== "3d") || p === null) return null;
  const source = fromBase64Url(p);
  return source === null ? null : { source, mode };
}
EOF
