import { DraftStore, ProgressStore, type KV } from "../src/storage";

const memory = (): KV & { data: Map<string, string> } => {
  const data = new Map<string, string>();
  return { data, getItem: (k) => data.get(k) ?? null, setItem: (k, v) => void data.set(k, v), removeItem: (k) => void data.delete(k) };
};

describe("drafts", () => {
  test("a fresh store starts in 2D with a starter program per mode", () => {
    const d = new DraftStore(memory());
    expect(d.getMode()).toBe("2d");
    expect(d.getDraft("2d")).toBe(exampleById("kwadrat")!.source);
    expect(d.getDraft("3d")).toBe(exampleById("schody")!.source);
  });
  test("drafts and the mode survive a reload (a new store on the same storage)", () => {
    const kv = memory();
    const a = new DraftStore(kv);
    a.setDraft("2d", "np 1");
    a.setDraft("3d", "gora 5");
    a.setMode("3d");
    const b = new DraftStore(kv);
    expect([b.getMode(), b.getDraft("2d"), b.getDraft("3d")]).toEqual(["3d", "np 1", "gora 5"]);
  });
  test("an emptied draft stays empty", () => {
    const kv = memory();
    new DraftStore(kv).setDraft("2d", "");
    expect(new DraftStore(kv).getDraft("2d")).toBe("");
  });
  test("works without any storage and when storage throws", () => {
    const none = new DraftStore(null);
    none.setDraft("2d", "np 2");
    expect(none.getDraft("2d")).toBe("np 2");
    const bad: KV = { getItem: () => { throw new Error("denied"); }, setItem: () => { throw new Error("full"); }, removeItem: () => { throw new Error("x"); } };
    const d = new DraftStore(bad);
    d.setDraft("3d", "np 3");
    expect(d.getDraft("3d")).toBe("np 3");
    expect(d.getMode()).toBe("2d");
  });
  test("loading over untouched or blank text needs no confirmation; over the user's own work it does", () => {
    const d = new DraftStore(memory());
    expect(d.needsConfirmation("2d")).toBe(false);
    d.setDraft("2d", "");
    expect(d.needsConfirmation("2d")).toBe(false);
    d.setDraft("2d", exampleById("gwiazda")!.source);
    expect(d.needsConfirmation("2d")).toBe(false);
    d.setDraft("2d", exampleById("gwiazda")!.source + "\nnp 1");
    expect(d.needsConfirmation("2d")).toBe(true);
  });
  test("replacing an unsaved draft keeps it recoverable", () => {
    const kv = memory();
    const d = new DraftStore(kv);
    d.setDraft("2d", "moja praca");
    d.replaceDraft("2d", exampleById("rozeta")!.source);
    expect(d.getDraft("2d")).toBe(exampleById("rozeta")!.source);
    expect(new DraftStore(kv).getBackup("2d")).toBe("moja praca");
  });
  test("replacing an untouched draft does not overwrite an existing backup", () => {
    const d = new DraftStore(memory());
    d.setDraft("2d", "moja praca");
    d.replaceDraft("2d", exampleById("rozeta")!.source);
    d.replaceDraft("2d", exampleById("gwiazda")!.source);
    expect(d.getBackup("2d")).toBe("moja praca");
  });
  test("restoring the backup swaps it back", () => {
    const d = new DraftStore(memory());
    d.setDraft("3d", "praca");
    d.replaceDraft("3d", "inna");
    expect(d.restoreBackup("3d")).toBe("praca");
    expect(d.getDraft("3d")).toBe("praca");
    expect(d.getBackup("3d")).toBeNull();
  });
  test("challenge drafts are kept per challenge", () => {
    const kv = memory();
    const d = new DraftStore(kv);
    d.setChallengeDraft("a", "np 1");
    expect(new DraftStore(kv).getChallengeDraft("a")).toBe("np 1");
    expect(d.getChallengeDraft("b")).toBe("");
  });
});

describe("challenge progress", () => {
  test("a pass is remembered across reloads and counts attempts", () => {
    const kv = memory();
    const p = new ProgressStore(kv);
    expect(p.isPassed("x")).toBe(false);
    p.record("x", false);
    p.record("x", true);
    const q = new ProgressStore(kv);
    expect(q.isPassed("x")).toBe(true);
    expect(q.attempts("x")).toBe(2);
    expect(q.passedCount()).toBe(1);
  });
  test("a later failure does not erase a pass", () => {
    const p = new ProgressStore(memory());
    p.record("x", true);
    p.record("x", false);
    expect(p.isPassed("x")).toBe(true);
  });
  test("corrupt stored data is ignored", () => {
    const kv = memory();
    kv.setItem("logomocja.progress", "{not json");
    expect(new ProgressStore(kv).isPassed("x")).toBe(false);
  });
  test("reset forgets everything", () => {
    const kv = memory();
    const p = new ProgressStore(kv);
    p.record("x", true);
    p.reset();
    expect(new ProgressStore(kv).passedCount()).toBe(0);
  });
});
