import { EXAMPLES, exampleById } from "./examples";
import type { Mode } from "./lang";

/** The slice of Web Storage the app relies on; lets tests inject an in-memory store. */
export interface KV {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

const STARTER: Record<Mode, string> = { "2d": "kwadrat", "3d": "schody" };

/** Wraps a possibly missing or failing storage; falls back to memory so the app keeps working. */
class Safe {
  private mem = new Map<string, string>();
  constructor(private kv: KV | null) {}
  get(key: string): string | null {
    if (this.mem.has(key)) return this.mem.get(key)!;
    try {
      return this.kv ? this.kv.getItem(key) : null;
    } catch {
      return null;
    }
  }
  set(key: string, value: string) {
    this.mem.set(key, value);
    try {
      this.kv?.setItem(key, value);
    } catch {
      /* quota or privacy mode: keep the in-memory copy */
    }
  }
  remove(key: string) {
    this.mem.delete(key);
    try {
      this.kv?.removeItem(key);
    } catch {
      /* ignore */
    }
  }
}

export class DraftStore {
  private s: Safe;
  constructor(kv: KV | null) {
    this.s = new Safe(kv);
  }

  getMode(): Mode {
    return this.s.get("logomocja.mode") === "3d" ? "3d" : "2d";
  }
  setMode(mode: Mode) {
    this.s.set("logomocja.mode", mode);
  }

  getDraft(mode: Mode): string {
    return this.s.get(`logomocja.draft.${mode}`) ?? exampleById(STARTER[mode])!.source;
  }
  setDraft(mode: Mode, text: string) {
    this.s.set(`logomocja.draft.${mode}`, text);
  }

  /** True when replacing the draft would throw away something the user wrote. */
  needsConfirmation(mode: Mode): boolean {
    const text = this.getDraft(mode);
    return text.trim() !== "" && !EXAMPLES.some((e) => e.source === text);
  }

  /** Replaces the draft; the user's own text, if any, is kept as a backup. */
  replaceDraft(mode: Mode, text: string) {
    if (this.needsConfirmation(mode)) this.s.set(`logomocja.backup.${mode}`, this.getDraft(mode));
    this.setDraft(mode, text);
  }
  getBackup(mode: Mode): string | null {
    return this.s.get(`logomocja.backup.${mode}`);
  }
  restoreBackup(mode: Mode): string | null {
    const b = this.getBackup(mode);
    if (b === null) return null;
    this.setDraft(mode, b);
    this.s.remove(`logomocja.backup.${mode}`);
    return b;
  }

  getChallengeDraft(id: string): string {
    return this.s.get(`logomocja.challenge.${id}`) ?? "";
  }
  setChallengeDraft(id: string, text: string) {
    this.s.set(`logomocja.challenge.${id}`, text);
  }
}

interface Entry {
  passed: boolean;
  attempts: number;
}

export class ProgressStore {
  private s: Safe;
  private data: Record<string, Entry> = {};
  constructor(kv: KV | null) {
    this.s = new Safe(kv);
    try {
      const raw = this.s.get("logomocja.progress");
      const parsed = raw ? JSON.parse(raw) : {};
      if (parsed && typeof parsed === "object") this.data = parsed;
    } catch {
      this.data = {};
    }
  }
  private save() {
    this.s.set("logomocja.progress", JSON.stringify(this.data));
  }
  record(id: string, passed: boolean) {
    const e = this.data[id] ?? { passed: false, attempts: 0 };
    this.data[id] = { passed: e.passed || passed, attempts: e.attempts + 1 };
    this.save();
  }
  isPassed(id: string): boolean {
    return this.data[id]?.passed === true;
  }
  attempts(id: string): number {
    return this.data[id]?.attempts ?? 0;
  }
  passedCount(): number {
    return Object.values(this.data).filter((e) => e.passed).length;
  }
  reset() {
    this.data = {};
    this.s.remove("logomocja.progress");
  }
}
