import { describe, expect, test } from "bun:test";
import { CHALLENGES, challengeById, checkChallenge } from "../src/challenges";
import { exampleById } from "../src/examples";

describe("challenges", () => {
  test("there are at least five, each with a mode, a Polish task text and an id", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    for (const c of CHALLENGES) {
      expect(["2d", "3d"]).toContain(c.mode);
      expect(c.title.length).toBeGreaterThan(2);
      expect(c.task.length).toBeGreaterThan(20);
    }
    expect(CHALLENGES.some((c) => c.mode === "3d")).toBe(true);
  });

  test("every task can be solved by its own reference program", () => {
    for (const c of CHALLENGES) {
      const r = checkChallenge(c.id, c.solution);
      expect(r.passed, `${c.id}: ${r.reason}`).toBe(true);
    }
  });

  test("a square drawn another way (different order, turns and splits) passes", () => {
    const r = checkChallenge("kwadrat", "pw 90 np 100 lw 90 np 50 np 50 lw 90 np 100 lw 90 np 100");
    expect(r.passed).toBe(true);
    expect(r.reason).toContain("Zadanie");
  });

  test("colour and width do not matter", () => {
    expect(checkChallenge("kwadrat", 'kolor "#c1763d" grubosc 9 powtorz 4 [np 100 pw 90]').passed).toBe(true);
  });

  test("small inaccuracies are tolerated, big ones are not", () => {
    expect(checkChallenge("kwadrat", "powtorz 4 [np 99.5 pw 90]").passed).toBe(true);
    const r = checkChallenge("kwadrat", "powtorz 4 [np 90 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason.length).toBeGreaterThan(10);
  });

  test("an empty drawing fails with a reason", () => {
    const r = checkChallenge("kwadrat", "pod np 100");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("Nic nie narysowano");
  });

  test("a partial drawing reports what is missing", () => {
    const r = checkChallenge("kwadrat", "np 100 pw 90 np 100");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("Brakuje");
  });

  test("a drawing with extra lines is reported", () => {
    const r = checkChallenge("kwadrat", "powtorz 4 [np 100 pw 90] pw 45 np 100");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("dodatkowe");
  });

  test("a program with an error fails and names the problem", () => {
    const r = checkChallenge("kwadrat", "np 100\nfoo");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("wierszu 2");
    expect(r.reason).toContain("foo");
  });

  test("the mirrored square is a different drawing", () => {
    expect(checkChallenge("kwadrat", "powtorz 4 [np 100 lw 90]").passed).toBe(false);
  });

  test("the cube challenge accepts the standard Sześcian program and rejects a flat square", () => {
    const cube = CHALLENGES.find((c) => c.id === "szescian")!;
    expect(cube.mode).toBe("3d");
    expect(checkChallenge("szescian", exampleById("szescian")!.source).passed).toBe(true);
    expect(checkChallenge("szescian", "powtorz 4 [np 100 pw 90]").passed).toBe(false);
  });

  test("3D commands in a 2D challenge are reported as errors", () => {
    const r = checkChallenge("kwadrat", "gora 90 np 100");
    expect(r.passed).toBe(false);
  });

  test("an unknown challenge id throws", () => {
    expect(() => checkChallenge("nie-ma", "np 1")).toThrow();
    expect(challengeById("nie-ma")).toBeUndefined();
  });

  test("the target drawing is available for display", () => {
    expect(challengeById("kwadrat")!.target().length).toBeGreaterThanOrEqual(4);
  });
});
