type V = [number, number, number];

function distToSegment(p: V, a: V, b: V): number {
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
  const len2 = dx * dx + dy * dy + dz * dz;
  let t = len2 === 0 ? 0 : ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy + (p[2] - a[2]) * dz) / len2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy), p[2] - (a[2] + t * dz));
}

function samples(segs: Segment[], step: number): V[] {
  const out: V[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(len / step));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      out.push([s.from[0] + (s.to[0] - s.from[0]) * t, s.from[1] + (s.to[1] - s.from[1]) * t, s.from[2] + (s.to[2] - s.from[2]) * t]);
    }
  }
  return out;
}

/** Share of `from` sample points that lie farther than `tol` from every segment of `to`. */
function uncovered(from: Segment[], to: Segment[], tol: number, step: number): number {
  const pts = samples(from, step);
  let far = 0;
  for (const p of pts) {
    let near = false;
    for (const s of to) {
      if (distToSegment(p, s.from, s.to) <= tol) {
        near = true;
        break;
      }
    }
    if (!near) far++;
  }
  return pts.length ? far / pts.length : 0;
}

const ALLOWED_SHARE = 0.02;

/** Runs `source` in the challenge's mode and compares the strokes with the expected drawing, ignoring colour, width and stroke order. */
export function checkChallenge(id: string, source: string): Verdict {
  const c = challengeById(id);
  if (!c) throw new Error(`Nieznane wyzwanie: ${id}`);
  const result = run(source, c.mode);
  if (result.error) {
    const e = result.error;
    return { passed: false, reason: `Program zawiera błąd w wierszu ${e.line}, kolumnie ${e.column}: ${e.message}` };
  }
  if (result.segments.length === 0) return { passed: false, reason: "Nic nie narysowano — żółw miał opuszczone pióro?" };
  const target = c.target();
  let size = 0;
  for (const s of target) for (const p of [s.from, s.to]) size = Math.max(size, Math.hypot(p[0], p[1], p[2]));
  const tol = Math.max(2, size * 0.015);
  const step = Math.max(tol / 2, 1);
  const missing = uncovered(target, result.segments, tol, step);
  const extra = uncovered(result.segments, target, tol, step);
  const pct = (x: number) => `${Math.round(x * 100)}%`;
  if (missing > ALLOWED_SHARE) {
    return { passed: false, reason: `Brakuje części rysunku: ${pct(missing)} szukanego kształtu nie ma na twoim obrazku (tolerancja ${tol.toFixed(1)}).` };
  }
  if (extra > ALLOWED_SHARE) {
    return { passed: false, reason: `Na rysunku są dodatkowe linie: ${pct(extra)} twojego rysunku leży poza szukanym kształtem.` };
  }
  return { passed: true, reason: "Zadanie wykonane — rysunek zgadza się ze wzorem." };
}
