import { run, type Mode } from "./lang";

/** File name for a downloaded program: ASCII slug of the title, or one named after the mode. */
export function logoFileName(mode: Mode, title?: string): string {
  const slug = (title ?? "")
    .toLowerCase()
    .replace(/ł/g, "l")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return `${slug || `logomocja-${mode}`}.logo`;
}

export function normalizeOpened(text: string): string {
  return text.replace(/^﻿/, "").replace(/\r\n|\r/g, "\n");
}

/** A file has no mode of its own: keep the current one unless the program only works in the other. */
export function guessMode(source: string, current: Mode): Mode {
  if (!run(source, current).error) return current;
  const other: Mode = current === "2d" ? "3d" : "2d";
  return run(source, other).error ? current : other;
}
EOF
