import { describe, expect, test } from "bun:test";
import { boundsOf, cameraPosition, fit2d, fit3d, project3d, toScreen2d } from "../src/render/camera";

const seg = (from: number[], to: number[]) => ({ from: from as [number, number, number], to: to as [number, number, number], color: "#000000", width: 1 });

describe("2D fit", () => {
  test("the whole drawing lands inside the canvas with a margin, centred", () => {
    const b = boundsOf([seg([0, 0, 0], [100, 100, 0]), seg([100, 100, 0], [200, 0, 0])])!;
    const v = fit2d(b, 400, 300);
    for (const p of [[0, 0], [200, 100], [0, 100], [200, 0]]) {
      const [x, y] = toScreen2d(v, 400, 300, p[0], p[1]);
      expect(x).toBeGreaterThan(0);
      expect(x).toBeLessThan(400);
      expect(y).toBeGreaterThan(0);
      expect(y).toBeLessThan(300);
    }
    const [cx, cy] = toScreen2d(v, 400, 300, 100, 50);
    expect(cx).toBeCloseTo(200, 6);
    expect(cy).toBeCloseTo(150, 6);
  });
  test("+Y points up on screen and +X to the right", () => {
    const v = fit2d(null, 400, 300);
    const o = toScreen2d(v, 400, 300, 0, 0);
    const up = toScreen2d(v, 400, 300, 0, 10);
    const right = toScreen2d(v, 400, 300, 10, 0);
    expect(up[1]).toBeLessThan(o[1]);
    expect(right[0]).toBeGreaterThan(o[0]);
  });
  test("an empty drawing still shows the origin", () => {
    const v = fit2d(null, 400, 300);
    const [x, y] = toScreen2d(v, 400, 300, 0, 0);
    expect(x).toBeGreaterThan(0);
    expect(x).toBeLessThan(400);
    expect(y).toBeGreaterThan(0);
    expect(y).toBeLessThan(300);
  });
  test("a single point or a vertical line does not divide by zero", () => {
    const v = fit2d(boundsOf([seg([0, 0, 0], [0, 100, 0])])!, 400, 300);
    expect(Number.isFinite(v.scale)).toBe(true);
    expect(v.scale).toBeGreaterThan(0);
  });
});

describe("3D fit and projection", () => {
  const cube = boundsOf([seg([0, 0, 0], [100, 100, 100])])!;
  test("all corners of the bounding box are visible after fit", () => {
    const v = fit3d(cube, 500, 400);
    for (const x of [0, 100]) for (const y of [0, 100]) for (const z of [0, 100]) {
      const p = project3d(v, 500, 400, [x, y, z])!;
      expect(p).not.toBeNull();
      expect(p.depth).toBeGreaterThan(0);
      expect(p.x).toBeGreaterThan(0);
      expect(p.x).toBeLessThan(500);
      expect(p.y).toBeGreaterThan(0);
      expect(p.y).toBeLessThan(400);
    }
  });
  test("it fits on a tall phone-sized canvas too", () => {
    const v = fit3d(cube, 300, 500);
    for (const c of [[0, 0, 0], [100, 100, 100], [100, 0, 100], [0, 100, 0]]) {
      const p = project3d(v, 300, 500, c as [number, number, number])!;
      expect(p.x).toBeGreaterThan(0);
      expect(p.x).toBeLessThan(300);
    }
  });
  test("up is up on screen: a higher point has a smaller y", () => {
    const v = fit3d(cube, 500, 400);
    expect(project3d(v, 500, 400, [50, 50, 100])!.y).toBeLessThan(project3d(v, 500, 400, [50, 50, 0])!.y);
  });
  test("points behind the camera are not projected", () => {
    const v = fit3d(cube, 500, 400);
    const cam = cameraPosition(v);
    const behind: [number, number, number] = [cam[0] * 2 - v.target[0], cam[1] * 2 - v.target[1], cam[2] * 2 - v.target[2]];
    expect(project3d(v, 500, 400, behind)).toBeNull();
  });
});
EOF
bun test ./test/camera.test.ts 2>&1 | tail -2

