import type { Segment, Vec } from "../lang";

export interface Bounds {
  min: Vec;
  max: Vec;
}

export function boundsOf(segs: Segment[]): Bounds | null {
  if (segs.length === 0) return null;
  const min: Vec = [Infinity, Infinity, Infinity];
  const max: Vec = [-Infinity, -Infinity, -Infinity];
  for (const s of segs) {
    for (const p of [s.from, s.to]) {
      for (let k = 0; k < 3; k++) {
        if (p[k] < min[k]) min[k] = p[k];
        if (p[k] > max[k]) max[k] = p[k];
      }
    }
  }
  return { min, max };
}

/* ---------- 2D: pan and zoom over the XY plane, +Y up ---------- */

export interface View2D {
  /** world point shown in the middle of the canvas */
  cx: number;
  cy: number;
  /** pixels per world unit */
  scale: number;
}

const DEFAULT_HALF_EXTENT = 150;
const MAX_FIT_SCALE = 50;

export function fit2d(b: Bounds | null, w: number, h: number): View2D {
  if (!b) return { cx: 0, cy: 0, scale: Math.min(w, h) / (2 * DEFAULT_HALF_EXTENT) };
  const bw = Math.max(b.max[0] - b.min[0], 1e-9);
  const bh = Math.max(b.max[1] - b.min[1], 1e-9);
  const pad = 1.16;
  const scale = Math.min(MAX_FIT_SCALE, w / (bw * pad), h / (bh * pad));
  return { cx: (b.min[0] + b.max[0]) / 2, cy: (b.min[1] + b.max[1]) / 2, scale: Math.max(scale, 1e-6) };
}

export function toScreen2d(v: View2D, w: number, h: number, x: number, y: number): [number, number] {
  return [w / 2 + (x - v.cx) * v.scale, h / 2 - (y - v.cy) * v.scale];
}

export function toWorld2d(v: View2D, w: number, h: number, sx: number, sy: number): [number, number] {
  return [v.cx + (sx - w / 2) / v.scale, v.cy - (sy - h / 2) / v.scale];
}

export function pan2d(v: View2D, dxPx: number, dyPx: number): View2D {
  return { ...v, cx: v.cx - dxPx / v.scale, cy: v.cy + dyPx / v.scale };
}

/** Zooms by `factor` keeping the world point under (sx, sy) fixed. */
export function zoomAt2d(v: View2D, w: number, h: number, sx: number, sy: number, factor: number): View2D {
  const scale = Math.min(1e4, Math.max(1e-4, v.scale * factor));
  const [wx, wy] = toWorld2d(v, w, h, sx, sy);
  return { scale, cx: wx - (sx - w / 2) / scale, cy: wy + (sy - h / 2) / scale };
}

/* ---------- 3D: orbit camera, Z up, perspective ---------- */

export interface View3D {
  target: Vec;
  /** rotation around Z in radians; 0 looks along +Y from the -Y side */
  az: number;
  /** elevation above the XY plane in radians */
  el: number;
  dist: number;
}

export const FOV = (45 * Math.PI) / 180;
const EL_LIMIT = (89 * Math.PI) / 180;

export const DEFAULT_ANGLES = { az: (35 * Math.PI) / 180, el: (25 * Math.PI) / 180 };

const sub = (a: Vec, b: Vec): Vec => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec, b: Vec) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec, b: Vec): Vec => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec): Vec => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};

export function cameraPosition(v: View3D): Vec {
  const c = Math.cos(v.el);
  return [v.target[0] + v.dist * Math.sin(v.az) * c, v.target[1] - v.dist * Math.cos(v.az) * c, v.target[2] + v.dist * Math.sin(v.el)];
}

export function cameraBasis(v: View3D): { pos: Vec; f: Vec; right: Vec; up: Vec } {
  const pos = cameraPosition(v);
  const f = norm(sub(v.target, pos));
  const right = norm(cross(f, [0, 0, 1]));
  const up = cross(right, f);
  return { pos, f, right, up };
}

export function fit3d(b: Bounds | null, w: number, h: number): View3D {
  let target: Vec = [0, 0, 0];
  let radius = DEFAULT_HALF_EXTENT;
  if (b) {
    target = [(b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2];
    radius = Math.max(Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2, 1);
  }
  const halfV = FOV / 2;
  const halfH = Math.atan(Math.tan(halfV) * (w / h));
  const dist = (radius / Math.sin(Math.min(halfV, halfH))) * 1.12;
  return { target, ...DEFAULT_ANGLES, dist };
}

export interface Projected {
  x: number;
  y: number;
  depth: number;
}

export function project3d(v: View3D, w: number, h: number, p: Vec): Projected | null {
  return projectWith(cameraBasis(v), w, h, p);
}

export type Basis = ReturnType<typeof cameraBasis>;

export function projectWith(basis: Basis, w: number, h: number, p: Vec): Projected | null {
  const d = sub(p, basis.pos);
  const z = dot(d, basis.f);
  if (z <= 1e-6) return null;
  const focal = h / 2 / Math.tan(FOV / 2);
  return { x: w / 2 + (dot(d, basis.right) / z) * focal, y: h / 2 - (dot(d, basis.up) / z) * focal, depth: z };
}

export function orbit(v: View3D, dxPx: number, dyPx: number): View3D {
  const el = Math.max(-EL_LIMIT, Math.min(EL_LIMIT, v.el + dyPx * 0.008));
  return { ...v, az: v.az - dxPx * 0.008, el };
}

export function pan3d(v: View3D, dxPx: number, dyPx: number, h: number): View3D {
  const { right, up } = cameraBasis(v);
  const unit = (2 * v.dist * Math.tan(FOV / 2)) / h;
  const k = (a: number, b: number) => -dxPx * unit * right[a] + dyPx * unit * up[a] + 0 * b;
  return { ...v, target: [v.target[0] + k(0, 0), v.target[1] + k(1, 0), v.target[2] + k(2, 0)] };
}

export function zoom3d(v: View3D, factor: number): View3D {
  return { ...v, dist: Math.min(1e7, Math.max(1, v.dist / factor)) };
}
