cat >> test/camera.test.ts <<'EOF'

import { orbit, pan2d, toWorld2d, zoom3d, zoomAt2d } from "../src/render/camera";

describe("interaction", () => {
  test("zooming keeps the point under the cursor fixed", () => {
    const v = { cx: 10, cy: 20, scale: 2 };
    const before = toWorld2d(v, 400, 300, 123, 77);
    const z = zoomAt2d(v, 400, 300, 123, 77, 1.5);
    expect(z.scale).toBeCloseTo(3, 9);
    const after = toWorld2d(z, 400, 300, 123, 77);
    expect(after[0]).toBeCloseTo(before[0], 9);
    expect(after[1]).toBeCloseTo(before[1], 9);
  });
  test("dragging pans the drawing with the pointer", () => {
    const v = pan2d({ cx: 0, cy: 0, scale: 2 }, 20, 10);
    expect(toWorld2d(v, 100, 100, 50 + 20, 50 + 10)).toEqual([0, 0]);
  });
  test("orbit never flips over the poles and zoom is bounded", () => {
    let v = fit3d(null, 400, 300);
    v = orbit(v, 0, 1e6);
    expect(v.el).toBeLessThan(Math.PI / 2);
    v = orbit(v, 0, -1e6);
    expect(v.el).toBeGreaterThan(-Math.PI / 2);
    expect(zoom3d(v, 1e12).dist).toBeGreaterThanOrEqual(1);
  });
});
EOF
