  for (let i = 0; i < segs.length; i++) {
    const p = pts[i];
    if (!p) continue;
    const s = segs[i];
    if (!open || s.color !== color || s.width !== width) {
      if (open) ctx.stroke();
      ctx.beginPath();
      color = s.color;
      width = s.width;
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
