import type { Mode } from "../lang";
import type { Turtle } from "../exec/controller";
import {
  boundsOf, fit2d, fit3d, orbit, pan2d, pan3d, zoom3d, zoomAt2d, DEFAULT_ANGLES,
  type View2D, type View3D,
} from "./camera";
import { draw2d, draw3d } from "./draw";

const START_TURTLE: Turtle = { pos: [0, 0, 0], h: [0, 1, 0], r: [1, 0, 0], u: [0, 0, 1], penDown: true, color: "#16866a", width: 3 };

