export class Stage {
  private ctx: CanvasRenderingContext2D;
  private mode: Mode = "2d";
  private v2: View2D = { cx: 0, cy: 0, scale: 1 };
  private v3: View3D = { target: [0, 0, 0], ...DEFAULT_ANGLES, dist: 400 };
  private segments: Segment[] = [];
