    if (typeof ResizeObserver !== "undefined") {
      this.ro = new ResizeObserver(() => {
        const first = !this.sized;
        this.measure();
        if (first) this.fit();
        this.invalidate();
      });
      this.ro.observe(canvas);
    }
    if (interactive) this.bind();
  }

  setMode(mode: Mode) {
    if (mode === this.mode) return;
    this.mode = mode;
    this.fit();
  }

  setScene(segments: Segment[], turtle: Turtle, showTurtle = true) {
    this.segments = segments;
    this.turtle = turtle;
    this.showTurtle = showTurtle;
    this.invalidate();
  }

  /** Frames the whole drawing. */
  fit() {
    this.measure();
    const b = boundsOf(this.segments);
    if (this.mode === "2d") this.v2 = fit2d(b, this.w, this.h);
    else this.v3 = { ...fit3d(b, this.w, this.h), az: this.v3.az, el: this.v3.el };
