        const mid = this.pinchCenter();
        if (this.lastPinch > 0 && d > 0) this.zoomAtPoint(d / this.lastPinch, mid.x, mid.y);
        this.lastPinch = d;
        this.pan(dx / 2, dy / 2);
      } else if (this.mode === "3d" && !(e.shiftKey || e.buttons & 2 || e.buttons & 4)) {
        this.v3 = orbit(this.v3, dx, dy);
        this.invalidate();
      } else this.pan(dx, dy);
    });
    const end = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      this.lastPinch = this.pinchDistance();
    };
    on("pointerup", end);
    on("pointercancel", end);
