      let handled = true;
      switch (e.key) {
        case "ArrowLeft": this.keyMove(step, 0); break;
        case "ArrowRight": this.keyMove(-step, 0); break;
        case "ArrowUp": this.keyMove(0, step); break;
        case "ArrowDown": this.keyMove(0, -step); break;
