  private keyMove(dx: number, dy: number) {
    if (this.mode === "3d") {
      this.v3 = orbit(this.v3, dx, dy);
      this.invalidate();
    } else this.pan(dx, dy);
  }

  private pan(dx: number, dy: number) {
    if (this.mode === "2d") this.v2 = pan2d(this.v2, dx, dy);
    else this.v3 = pan3d(this.v3, dx, dy, this.h);
    this.invalidate();
  }

  private zoomAtPoint(factor: number, x: number, y: number) {
    if (this.mode === "2d") this.v2 = zoomAt2d(this.v2, this.w, this.h, x, y, factor);
    else this.v3 = zoom3d(this.v3, factor);
    this.invalidate();
  }

  private pinchDistance(): number {
    const p = [...this.pointers.values()];
    return p.length >= 2 ? Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) : 0;
  }

  private pinchCenter() {
    const p = [...this.pointers.values()];
    return { x: (p[0].x + p[1].x) / 2, y: (p[0].y + p[1].y) / 2 };
  }
}
