import { describe, expect, test } from "bun:test";
import { highlightLine } from "../src/ui/highlight";

const kinds = (line: string, procs: string[] = []) => highlightLine(line, new Set(procs)).filter((t) => t.cls !== "plain").map((t) => [t.text, t.cls]);

