    expect(kinds('np 12.5 kolor "#16866a" [pw .5] ; koniec')).toEqual([
      ["np", "cmd"], ["12.5", "num"], ["kolor", "cmd"], ['"#16866a"', "str"], ["[", "bracket"], ["pw", "cmd"], [".5", "num"], ["]", "bracket"], ["; koniec", "comment"],
    ]);
  });
  test("control words, special words, operators and names", () => {
    expect(kinds("powtorz 3 [np nrpowt * bok + :kąt]")).toEqual([
      ["powtorz", "ctl"], ["3", "num"], ["[", "bracket"], ["np", "cmd"], ["nrpowt", "special"], ["*", "op"], ["bok", "name"], ["+", "op"], [":kąt", "name"], ["]", "bracket"],
    ]);
  });
