import type { LangError, Pos } from "../lang";
import { definedProcedures, highlightLine, type Piece } from "./highlight";

export interface EditorOptions {
  onInput(text: string): void;
  /** called for Ctrl/Cmd+Enter inside the editor */
  onRun?(): void;
  label: string;
}

/** Marks characters [start, end) of a line's pieces with an extra class by splitting pieces at the range borders. */
export function markRange(pieces: Piece[], start: number, end: number, extra: string): { text: string; cls: string }[] {
  const out: { text: string; cls: string }[] = [];
  let pos = 0;
  for (const p of pieces) {
    const a = pos, b = pos + p.text.length;
    pos = b;
    const s = Math.max(a, start), e = Math.min(b, end);
    if (s >= e) {
      out.push({ text: p.text, cls: p.cls });
      continue;
    }
    if (s > a) out.push({ text: p.text.slice(0, s - a), cls: p.cls });
    out.push({ text: p.text.slice(s - a, e - a), cls: `${p.cls} ${extra}` });
    if (e < b) out.push({ text: p.text.slice(e - a), cls: p.cls });
  }
  return out;
}

export class Editor {
  readonly el: HTMLDivElement;
  private gutter: HTMLDivElement;
  private gutterInner: HTMLDivElement;
  private hl: HTMLPreElement;
  private input: HTMLTextAreaElement;
  private error: LangError | null = null;
  private current: Pos | null = null;
  private lineHeight = 22;

  constructor(private opts: EditorOptions) {
    this.el = document.createElement("div");
    this.el.className = "editor";
    this.gutter = document.createElement("div");
    this.gutter.className = "gutter";
    this.gutter.setAttribute("aria-hidden", "true");
    this.gutterInner = document.createElement("div");
    this.gutter.append(this.gutterInner);
    const code = document.createElement("div");
    code.className = "code";
    this.hl = document.createElement("pre");
    this.hl.className = "hl";
    this.hl.setAttribute("aria-hidden", "true");
    this.input = document.createElement("textarea");
    this.input.className = "input";
    this.input.spellcheck = false;
    this.input.autocapitalize = "off";
    this.input.setAttribute("autocomplete", "off");
    this.input.setAttribute("autocorrect", "off");
    this.input.setAttribute("wrap", "off");
    this.input.setAttribute("aria-label", opts.label);
    code.append(this.hl, this.input);
    this.el.append(this.gutter, code);

    this.input.addEventListener("input", () => {
      this.error = null;
      this.render();
      opts.onInput(this.input.value);
    });
    this.input.addEventListener("scroll", () => this.syncScroll());
    this.input.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        opts.onRun?.();
      } else if (e.key === "Enter" && !e.shiftKey && !e.altKey && !e.ctrlKey && !e.metaKey) this.autoIndent(e);
    });
    this.render();
  }

  get value(): string {
    return this.input.value;
  }

  setValue(text: string) {
    this.input.value = text;
    this.error = null;
    this.render();
    this.input.scrollTop = 0;
    this.input.scrollLeft = 0;
    this.syncScroll();
  }

  focus() {
    this.input.focus();
  }

  setError(e: LangError | null) {
    this.error = e;
    this.render();
    if (e) this.reveal(e.line);
  }

  /** Highlights the line about to run (or running); null clears it. */
  setCurrent(p: Pos | null) {
    const changed = (p?.line ?? 0) !== (this.current?.line ?? 0);
    this.current = p;
    if (changed) {
      this.render();
      if (p) this.reveal(p.line);
    }
  }

  private autoIndent(e: KeyboardEvent) {
    const t = this.input;
    if (t.selectionStart !== t.selectionEnd) return;
    const before = t.value.slice(0, t.selectionStart);
    const line = before.slice(before.lastIndexOf("\n") + 1);
    const indent = /^[ \t]*/.exec(line)![0];
    const extra = /\[\s*$/.test(line) && !indent.length ? "  " : /\[\s*$/.test(line) ? "  " : "";
    if (!indent && !extra) return;
    e.preventDefault();
    const text = "\n" + indent + extra;
    if (!document.execCommand?.("insertText", false, text)) {
      t.setRangeText(text, t.selectionStart, t.selectionEnd, "end");
      t.dispatchEvent(new Event("input"));
    }
  }

  private syncScroll() {
    const x = -this.input.scrollLeft, y = -this.input.scrollTop;
    this.hl.style.transform = `translate(${x}px, ${y}px)`;
    this.gutterInner.style.transform = `translateY(${y}px)`;
  }

  /** Scrolls the textarea so that the 1-based line is visible. */
  private reveal(line: number) {
    const t = this.input;
    const top = (line - 1) * this.lineHeight;
    if (top < t.scrollTop) t.scrollTop = top;
    else if (top + this.lineHeight * 2 > t.scrollTop + t.clientHeight) t.scrollTop = top + this.lineHeight * 2 - t.clientHeight;
    this.syncScroll();
  }

  private render() {
    const lines = this.input.value.split(/\r\n|\n|\r/);
    const procs = definedProcedures(this.input.value);
    const hlFrag = document.createDocumentFragment();
    const gutFrag = document.createDocumentFragment();
    lines.forEach((text, i) => {
      const n = i + 1;
      const isErr = this.error?.line === n;
      const isCur = this.current?.line === n;
      const row = document.createElement("div");
      row.className = "l" + (isCur ? " cur" : "") + (isErr ? " err" : "");
      let pieces: { text: string; cls: string }[] = highlightLine(text, procs);
      if (isErr) {
        const start = Math.min(Math.max(this.error!.column - 1, 0), text.length);
        const m = /^(?::?[\p{L}\p{N}_]+|\d*\.?\d+|"[^"]*"?|.)/u.exec(text.slice(start));
        pieces = markRange(highlightLine(text, procs), start, start + (m ? m[0].length : 1), "squiggle");
        if (!m) pieces.push({ text: " ", cls: "plain squiggle" });
      }
      for (const p of pieces) {
        if (p.cls === "plain") row.append(document.createTextNode(p.text));
        else {
          const s = document.createElement("span");
          s.className = "t-" + p.cls.replace(/ /g, " t-");
          s.textContent = p.text;
          row.append(s);
        }
      }
      if (text === "" && !isErr) row.append(document.createTextNode(" "));
      if (isErr) {
        const m = document.createElement("span");
        m.className = "errmsg";
        m.textContent = "  ⚠ " + this.error!.message;
        row.append(m);
      }
      hlFrag.append(row);
      const g = document.createElement("div");
      g.className = "n" + (isCur ? " cur" : "") + (isErr ? " err" : "");
      g.textContent = String(n);
      gutFrag.append(g);
    });
    this.hl.replaceChildren(hlFrag);
    this.gutterInner.replaceChildren(gutFrag);
    this.gutter.style.setProperty("--digits", String(Math.max(2, String(lines.length).length)));
  }
}
