  return span.firstElementChild as SVGSVGElement;
}

export interface DialogAction {
  label: string;
  value: string;
  primary?: boolean;
}

/** Opens a modal <dialog> (focus trap and Esc come from the browser) and resolves with the chosen action value, or "" if dismissed. */
export function modal(title: string, body: Node | string, actions: DialogAction[], opts: { wide?: boolean } = {}): Promise<string> {
  return new Promise((resolve) => {
    const dlg = h("dialog", { class: "dialog" + (opts.wide ? " wide" : ""), "aria-labelledby": "dlg-title" });
    let result = "";
    const bar = h("div", { class: "dialog-actions" });
    for (const a of actions) {
      bar.append(h("button", { type: "button", class: "btn" + (a.primary ? " primary" : ""), on: { click: () => { result = a.value; dlg.close(); } } }, a.label));
    }
    dlg.append(h("h2", { id: "dlg-title" }, title), h("div", { class: "dialog-body" }, body), bar);
    dlg.addEventListener("close", () => {
      dlg.remove();
      resolve(result);
    });
    document.body.append(dlg);
    dlg.showModal();
    (dlg.querySelector(".btn.primary") as HTMLElement | null)?.focus();
  });
}

export class Toasts {
  private box = h("div", { class: "toasts", role: "status", "aria-live": "polite" });
  constructor() {
    document.body.append(this.box);
  }
  show(text: string, action?: { label: string; run(): void }, ms = 6000) {
    const t = h("div", { class: "toast" }, h("span", null, text));
    if (action) {
      t.append(h("button", { type: "button", class: "btn small", on: { click: () => { action.run(); t.remove(); } } }, action.label));
    }
    this.box.append(t);
    setTimeout(() => t.remove(), ms);
  }
}

export function download(name: string, blob: Blob) {
  const url = URL.createObjectURL(blob);
  const a = h("a", { href: url, download: name });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
