import { CHALLENGES, challengeById, checkChallenge, type Challenge } from "../challenges";
import { Controller, type Snapshot } from "../exec/controller";
import { EXAMPLES, type Example } from "../examples";
import { guessMode, logoFileName, normalizeOpened } from "../files";
import { run, type Mode, type RunResult } from "../lang";
import { Stage } from "../render/stage";
import { encodePermalink } from "../share";
import type { DraftStore, ProgressStore } from "../storage";
import { download, h, icon, modal, Toasts } from "./dom";
import { Editor } from "./editor";

export interface Services {
  drafts: DraftStore;
  progress: ProgressStore;
  toasts: Toasts;
}

export type Context = { kind: "free" } | { kind: "challenge"; id: string };

/** Animation speeds in operations per second. */
const SPEEDS = [1, 3, 10, 30, 100, 300, 1000, 3000, Infinity];
const SPEED_LABELS = ["1 op/s", "3 op/s", "10 op/s", "30 op/s", "100 op/s", "300 op/s", "1000 op/s", "3000 op/s", "natychmiast"];
const DEFAULT_SPEED = 5;

const CHALLENGE_STARTER = (c: Challenge) => `; ${c.title}\n; Napisz program, który to narysuje.\n`;

export const SHORTCUTS: { keys: string[]; action: string }[] = [
  { keys: ["Ctrl+Enter", "Alt+R"], action: "Uruchom program" },
  { keys: ["Alt+K"], action: "Wykonaj jeden krok" },
  { keys: ["Alt+P"], action: "Wstrzymaj / wznów" },
  { keys: ["Alt+Z"], action: "Zeruj (reset) rysunek" },
  { keys: ["Strzałki"], action: "Przesuwanie rysunku (2D) lub obracanie sceny (3D), gdy płótno ma fokus" },
  { keys: ["+", "−"], action: "Przybliżanie i oddalanie, gdy płótno ma fokus" },
  { keys: ["0", "Home"], action: "Dopasuj rysunek / resetuj widok, gdy płótno ma fokus" },
];

export class Workspace {
  readonly el: HTMLElement;
  readonly controller: Controller;
  private editor: Editor;
  private stage: Stage | null = null;
  private ctx: Context = { kind: "free" };
  private mode: Mode;
  private autoFit = true;
  private speed = DEFAULT_SPEED;
  private budget = 0;
  private lastFrame = 0;
  private looping = false;
  private lastError: unknown = null;
  private previewStage: Stage | null = null;

  // elements
  private btnRun!: HTMLButtonElement;
  private btnStep!: HTMLButtonElement;
  private btnPause!: HTMLButtonElement;
  private btnReset!: HTMLButtonElement;
  private btnRestore!: HTMLButtonElement;
  private radios!: Record<Mode, HTMLInputElement>;
  private statusEl!: HTMLElement;
  private errorEl!: HTMLElement;
  private turtleEl!: HTMLElement;
  private speedOut!: HTMLElement;
  private taskEl!: HTMLElement;
  private stageNote!: HTMLElement;
  private fileInput!: HTMLInputElement;
  private canvas!: HTMLCanvasElement;

  constructor(private svc: Services) {
    this.mode = svc.drafts.getMode();
    this.controller = new Controller(() => this.sync());
    this.editor = new Editor({
      label: "Edytor programu Logo",
      onInput: (text) => this.onEdit(text),
      onRun: () => this.doRun(),
    });
    this.el = this.build();
    this.initStage();
    this.loadContext();
  }

  /* ------------------------------------------------------------ construction */

  private build(): HTMLElement {
    const drafts = this.svc.drafts;
    const btn = (label: string, ic: string, onClick: () => void, extra: Record<string, unknown> = {}) =>
      h("button", { type: "button", class: "btn", on: { click: onClick }, ...extra }, icon(ic), h("span", { class: "label" }, label));

    this.btnRun = btn("Uruchom", "play", () => this.doRun(), { class: "btn primary", "aria-keyshortcuts": "Control+Enter Alt+R", title: "Uruchom program (Ctrl+Enter)" });
    this.btnStep = btn("Krok", "step", () => this.doStep(), { "aria-keyshortcuts": "Alt+K", title: "Wykonaj jedno polecenie (Alt+K)" });
    this.btnPause = btn("Pauza", "pause", () => this.doPause(), { "aria-keyshortcuts": "Alt+P", title: "Wstrzymaj lub wznów (Alt+P)" });
    this.btnReset = btn("Reset", "reset", () => this.doReset(), { "aria-keyshortcuts": "Alt+Z", title: "Wyczyść rysunek i zacznij od nowa (Alt+Z)" });

    const range = h("input", {
      type: "range", id: "speed", min: "0", max: String(SPEEDS.length - 1), step: "1", value: String(this.speed),
      on: { input: (e: Event) => this.setSpeed(Number((e.target as HTMLInputElement).value)) },
    });
    this.speedOut = h("output", { for: "speed", class: "speed-out" }, SPEED_LABELS[this.speed]);
    const speed = h("div", { class: "speed" }, h("label", { for: "speed" }, "Prędkość"), range, this.speedOut);

    const radio = (m: Mode, text: string) => {
      const input = h("input", {
        type: "radio", name: "mode", value: m, id: `mode-${m}`,
        on: { change: () => this.switchMode(m) },
      });
      return { input, label: h("label", { class: "seg", for: `mode-${m}` }, input, h("span", null, text)) };
    };
    const r2 = radio("2d", "2D"), r3 = radio("3d", "3D");
    this.radios = { "2d": r2.input, "3d": r3.input };
    const modeGroup = h("div", { class: "segmented", role: "radiogroup", "aria-label": "Tryb rysowania" }, r2.label, r3.label);

    this.btnRestore = btn("Przywróć szkic", "undo", () => this.restoreBackup(), { title: "Przywróć szkic sprzed wczytania przykładu lub pliku", hidden: true });
    this.fileInput = h("input", { type: "file", accept: ".logo,.txt,text/plain", hidden: true, "aria-label": "Wybierz plik programu .logo", on: { change: () => this.onFile() } });

    const toolbar = h("div", { class: "toolbar", role: "toolbar", "aria-label": "Sterowanie programem" }, this.btnRun, this.btnStep, this.btnPause, this.btnReset, speed);
    const filebar = h(
      "div", { class: "toolbar secondary", role: "toolbar", "aria-label": "Tryb, przykłady i pliki" },
      modeGroup,
      btn("Przykłady", "gallery", () => this.openGallery(), { title: "Wybierz jeden z gotowych programów" }),
      this.btnRestore,
      h("span", { class: "grow" }),
      btn("Udostępnij", "share", () => this.share(), { title: "Skopiuj link z tym programem" }),
      btn("PNG", "image", () => this.exportPng(), { title: "Zapisz rysunek jako PNG" }),
      btn("Pobierz", "download", () => this.downloadLogo(), { title: "Pobierz program jako plik .logo" }),
      btn("Otwórz", "open", () => this.fileInput.click(), { title: "Otwórz plik .logo" }),
      this.fileInput,
    );

    this.taskEl = h("section", { class: "task", hidden: true, "aria-label": "Zadanie" });
    this.statusEl = h("div", { class: "status", role: "status", "aria-live": "polite" });
    this.errorEl = h("div", { class: "errorbox", role: "alert", hidden: true });

    const codePanel = h("section", { class: "panel code-panel", "aria-label": "Program" }, toolbar, filebar, this.taskEl, this.editor.el, this.errorEl, this.statusEl);

    this.canvas = h("canvas", {
      class: "stage", tabindex: "0", role: "img",
      "aria-label": "Rysunek żółwia. Strzałki przesuwają lub obracają widok, plus i minus przybliżają, zero dopasowuje.",
    });
    this.turtleEl = h("div", { class: "turtle-info", "aria-hidden": "true" });
    this.stageNote = h("p", { class: "stage-note", hidden: true, role: "note" });
    const vbtn = (label: string, ic: string, fn: () => void) =>
      h("button", { type: "button", class: "btn icon-only", title: label, "aria-label": label, on: { click: fn } }, icon(ic));
    const viewTools = h(
