    e.preventDefault();
    return true;
  }

  /* ------------------------------------------------------------ rendering state into the page */

  private sync() {
    if (!this.statusEl) return;
    const s = this.controller.snapshot();
    this.stage?.setScene(s.segments, s.turtle);
    if (this.autoFit && s.segments.length > 0 && this.stage && (s.state === "running" || s.state === "paused" || s.state === "finished" || s.state === "error")) this.stage.fit();
    this.editor.setCurrent(s.currentLine);
    if (s.error !== this.lastError) {
      this.lastError = s.error;
      this.editor.setError(s.error);
    }
    this.renderStatus(s);
  }

  private renderStatus(s: Snapshot) {
    const running = s.state === "running", paused = s.state === "paused";
    this.btnPause.disabled = !(running || paused);
    const pauseLabel = this.btnPause.querySelector(".label")!;
    pauseLabel.textContent = paused ? "Wznów" : "Pauza";
    this.btnPause.replaceChildren(icon(paused ? "play" : "pause"), pauseLabel);
    this.btnReset.disabled = s.state === "idle" && s.segments.length === 0 && !s.stale;

    let text: string;
    switch (s.state) {
      case "running": text = `Trwa wykonywanie programu… (operacji: ${s.ops})`; break;
      case "paused": text = s.currentLine ? `Wstrzymano. Następne polecenie: wiersz ${s.currentLine.line}.` : "Wstrzymano."; break;
      case "finished": text = `Gotowe: ${s.segments.length} ${plural(s.segments.length, "odcinek", "odcinki", "odcinków")}, ${s.ops} operacji.`; break;
      case "error": text = s.segments.length > 0 ? `Program zatrzymany. Zachowano ${s.segments.length} ${plural(s.segments.length, "odcinek", "odcinki", "odcinków")} narysowanych przed błędem.` : "Program nie został uruchomiony — nic nie narysowano."; break;
      default: text = s.stale ? "Kod został zmieniony — rysunek pochodzi z poprzedniego uruchomienia. Naciśnij Uruchom." : "Gotowy. Naciśnij Uruchom (Ctrl+Enter) albo wykonuj program krok po kroku.";
    }
    this.statusEl.textContent = text;
    this.errorEl.hidden = !s.error;
    this.errorEl.textContent = s.error ? `Błąd w wierszu ${s.error.line}, kolumnie ${s.error.column}: ${s.error.message}` : "";

    const t = s.turtle;
    const heading = (Math.round((Math.atan2(t.h[0], t.h[1]) * 180) / Math.PI * 10) / 10 + 360) % 360;
    const f = (n: number) => String(Math.round(n * 100) / 100);
    this.turtleEl.textContent = `Żółw: x ${f(t.pos[0])}, y ${f(t.pos[1])}${this.mode === "3d" ? `, z ${f(t.pos[2])}` : ""} · kurs ${f(heading)}° · pióro ${t.penDown ? "opuszczone" : "podniesione"}`;
