  /* ------------------------------------------------------------ challenges */

  private renderTask(c: Challenge) {
    const verdict = h("div", { class: "verdict", role: "status", "aria-live": "polite" });
    const canvas = h("canvas", { class: "preview", role: "img", "aria-label": `Wzór do narysowania: ${c.title}` });
