      h("div", { class: "task-head" }, h("h2", null, `Wyzwanie: ${c.title}`), h("span", { class: "badge" }, c.mode.toUpperCase()), passed ? h("span", { class: "badge ok" }, "zaliczone") : null),
      h("div", { class: "task-body" },
        h("div", null, h("p", null, c.task), h("details", null, h("summary", null, "Podpowiedź"), h("p", null, c.hint))),
        h("figure", { class: "task-figure" }, canvas, h("figcaption", null, "Wzór")),
      ),
      h("div", { class: "task-actions" }, check, h("a", { class: "btn", href: "#/wyzwania" }, "Wszystkie wyzwania"), verdict),
    );
    this.taskEl.hidden = false;
    try {
      const st = new Stage(canvas, false);
      st.setMode(c.mode);
      st.setScene(c.target(), { pos: [0, 0, 0], h: [0, 1, 0], r: [1, 0, 0], u: [0, 0, 1], penDown: true, color: "#16866a", width: 3 }, false);
      st.fit();
      this.previewStage = st;
    } catch {
      canvas.hidden = true;
    }
  }

  private checkTask(c: Challenge, verdictEl: HTMLElement) {
    const text = this.editor.value;
    const v = checkChallenge(c.id, text);
    this.svc.progress.record(c.id, v.passed);
    this.controller.load(text, this.mode);
    this.controller.runToEnd();
    verdictEl.className = "verdict " + (v.passed ? "pass" : "fail");
    verdictEl.textContent = (v.passed ? "✔ " : "✘ ") + v.reason;
    if (v.passed) this.svc.toasts.show(`Brawo! Zaliczone: ${c.title}.`);
  }

  /* ------------------------------------------------------------ gallery, sharing, files */

  async openGallery() {
    const stages: Stage[] = [];
    let chosen: Example | null = null;
    const grid = h("div", { class: "gallery" });
    for (const ex of EXAMPLES) {
      const canvas = h("canvas", { class: "thumb", "aria-hidden": "true" });
      const card = h("button", {
        type: "button", class: "card",
        on: { click: (e: Event) => { chosen = ex; (e.currentTarget as HTMLElement).closest("dialog")!.close(); } },
      }, canvas, h("span", { class: "card-title" }, ex.title, h("span", { class: "badge" }, ex.mode.toUpperCase())), h("span", { class: "card-blurb" }, ex.blurb));
      card.setAttribute("aria-label", `${ex.title} (${ex.mode.toUpperCase()}): ${ex.blurb}`);
      grid.append(card);
      queueMicrotask(() => {
        try {
          const st = new Stage(canvas, false);
          st.setMode(ex.mode);
          st.setScene(run(ex.source, ex.mode).segments, { pos: [0, 0, 0], h: [0, 1, 0], r: [1, 0, 0], u: [0, 0, 1], penDown: true, color: "#16866a", width: 3 }, false);
          stages.push(st);
        } catch {
          canvas.hidden = true;
        }
      });
    }
    await modal("Przykłady", grid, [{ label: "Zamknij", value: "" }], { wide: true });
    stages.forEach((s) => s.destroy());
    if (chosen) await this.loadExample(chosen);
  }

  async share() {
    const url = encodePermalink(this.editor.value, this.mode, location.href);
    try {
      await navigator.clipboard.writeText(url);
      this.svc.toasts.show("Skopiowano link do programu." + (url.length > 8000 ? " Uwaga: link jest bardzo długi i niektóre serwisy mogą go obciąć." : ""));
    } catch {
      const input = h("input", { type: "text", readonly: true, class: "share-input", value: url, "aria-label": "Link do programu", on: { focus: (e: Event) => (e.target as HTMLInputElement).select() } });
      await modal("Link do programu", h("div", null, h("p", null, "Skopiuj ten link (zaznacz go i naciśnij Ctrl+C):"), input), [{ label: "Zamknij", value: "", primary: true }]);
    }
  }

  async exportPng() {
    if (!this.stage) return;
    const blob = await this.stage.toBlob();
    if (!blob) {
      this.svc.toasts.show("Nie udało się utworzyć obrazu PNG.");
      return;
    }
    download(`logomocja-${this.mode}.png`, blob);
  }

  downloadLogo() {
    const title = this.ctx.kind === "challenge" ? challengeById(this.ctx.id)?.title : EXAMPLES.find((e) => e.source === this.editor.value)?.title;
    download(logoFileName(this.mode, title), new Blob([this.editor.value], { type: "text/plain;charset=utf-8" }));
  }

  private async onFile() {
    const file = this.fileInput.files?.[0];
    this.fileInput.value = "";
    if (!file) return;
    const text = normalizeOpened(await file.text());
    if (this.ctx.kind === "challenge") {
      this.editor.setValue(text);
      this.onEdit(text);
      return;
    }
    await this.adopt(text, guessMode(text, this.mode), { confirm: true, what: file.name });
  }

  focusEditor() {
    this.editor.focus();
  }

  /** Called when the workspace becomes visible, so canvases measure real sizes. */
  shown() {
    this.stage?.fit();
  }
}

function plural(n: number, one: string, few: string, many: string): string {
  if (n === 1) return one;
  const t = n % 10, hh = n % 100;
  return t >= 2 && t <= 4 && !(hh >= 12 && hh <= 14) ? few : many;
}

