    );
    const viewPanel = h("section", { class: "panel view-panel", "aria-label": "Rysunek" }, h("div", { class: "stage-wrap" }, this.canvas, viewTools), this.stageNote, this.turtleEl);

    drafts.getMode();
    return h("div", { class: "workspace" }, codePanel, viewPanel);
  }

  private initStage() {
    try {
      this.stage = new Stage(this.canvas, true, () => (this.autoFit = false));
      this.stage.setMode(this.mode);
    } catch (e) {
      this.stage = null;
      this.canvas.hidden = true;
      this.stageNote.hidden = false;
      this.stageNote.textContent = `Rysowanie jest wyłączone: ${(e as Error).message} Programy nadal można uruchamiać, a wynik odczytać przez window.logomocja.run.`;
    }
  }

  private viewAction(fn: () => void) {
    this.autoFit = false;
    fn();
  }

  /* ------------------------------------------------------------ context and drafts */

  get context(): Context {
    return this.ctx;
  }

  /** Switches between the free workspace and a challenge, saving the text of the one being left. */
  enter(ctx: Context) {
    const same = ctx.kind === this.ctx.kind && (ctx.kind === "free" || (this.ctx.kind === "challenge" && ctx.id === this.ctx.id));
    if (same) return;
    this.saveCurrent();
    this.ctx = ctx;
    this.loadContext();
  }

  private saveCurrent() {
    const text = this.editor.value;
    if (this.ctx.kind === "free") this.svc.drafts.setDraft(this.mode, text);
    else this.svc.drafts.setChallengeDraft(this.ctx.id, text);
  }

  private loadContext() {
    this.previewStage?.destroy();
    this.previewStage = null;
    let text: string;
    if (this.ctx.kind === "challenge") {
      const c = challengeById(this.ctx.id)!;
      this.mode = c.mode;
      text = this.svc.drafts.getChallengeDraft(c.id) || CHALLENGE_STARTER(c);
      this.renderTask(c);
    } else {
      this.mode = this.svc.drafts.getMode();
      text = this.svc.drafts.getDraft(this.mode);
      this.taskEl.hidden = true;
      this.taskEl.replaceChildren();
    }
    this.applyText(text);
  }

  /** Puts text and mode into the editor, controller and stage (no persistence side effects). */
  private applyText(text: string) {
    this.controller.reset();
    this.editor.setValue(text);
    this.controller.load(text, this.mode);
    this.stage?.setMode(this.mode);
    this.radios[this.mode].checked = true;
    const locked = this.ctx.kind === "challenge";
    for (const r of Object.values(this.radios)) {
      r.disabled = locked;
      r.parentElement!.title = locked ? "Tryb jest ustalony przez wyzwanie" : "";
    }
    this.autoFit = true;
    this.lastError = null;
    this.sync();
    this.stage?.fit();
    this.updateRestore();
  }

  private onEdit(text: string) {
    if (this.ctx.kind === "free") this.svc.drafts.setDraft(this.mode, text);
    else this.svc.drafts.setChallengeDraft(this.ctx.id, text);
    this.controller.load(text, this.mode);
  }

  private switchMode(m: Mode) {
    if (m === this.mode || this.ctx.kind !== "free") return;
    this.saveCurrent();
    this.svc.drafts.setMode(m);
    this.mode = m;
    this.applyText(this.svc.drafts.getDraft(m));
  }

  private updateRestore() {
    this.btnRestore.hidden = this.ctx.kind !== "free" || this.svc.drafts.getBackup(this.mode) === null;
  }

  private restoreBackup() {
    const b = this.svc.drafts.restoreBackup(this.mode);
    if (b === null) return;
    this.applyText(b);
    this.svc.toasts.show("Przywrócono poprzedni szkic.");
  }

  /**
   * Loads a program into the free workspace in the given mode. When the draft holds the user's own work the user
   * is asked first (unless `confirm` is false); the previous text is always kept as a backup.
   */
  async adopt(source: string, mode: Mode, opts: { confirm: boolean; what: string }): Promise<boolean> {
    this.enter({ kind: "free" });
    this.saveCurrent();
    const drafts = this.svc.drafts;
    if (opts.confirm && drafts.needsConfirmation(mode)) {
      const answer = await modal(
        "Zastąpić szkic?",
        `W trybie ${mode.toUpperCase()} masz własny, niezapisany program. Wczytanie „${opts.what}” go zastąpi. Poprzedni szkic zostanie zachowany i będzie można go przywrócić przyciskiem „Przywróć szkic”.`,
        [{ label: "Anuluj", value: "" }, { label: "Wczytaj", value: "ok", primary: true }],
      );
      if (answer !== "ok") return false;
    }
    const hadWork = drafts.needsConfirmation(mode);
    drafts.replaceDraft(mode, source);
    drafts.setMode(mode);
    this.mode = mode;
    this.applyText(source);
    if (hadWork) this.svc.toasts.show(`Wczytano „${opts.what}”. Poprzedni szkic został zachowany.`, { label: "Przywróć", run: () => this.restoreBackup() });
    return true;
  }

  async loadExample(ex: Example) {
    if (await this.adopt(ex.source, ex.mode, { confirm: true, what: ex.title })) this.editor.focus();
  }

  /** Loads and runs a program from a permalink without animation. */
  async loadShared(source: string, mode: Mode) {
    await this.adopt(source, mode, { confirm: false, what: "program z linku" });
    this.controller.runToEnd();
    this.autoFit = true;
    this.stage?.fit();
  }

  /** Testing hook: as if the program was pasted, then run to the end and fit. */
  async openProgram(source: string, mode: Mode): Promise<RunResult> {
    this.enter({ kind: "free" });
    this.svc.drafts.setMode(mode);
    this.svc.drafts.setDraft(mode, source);
    this.mode = mode;
    this.applyText(source);
    this.controller.runToEnd();
    this.autoFit = true;
    this.stage?.fit();
    this.stage?.flush();
    await new Promise<void>((r) => requestAnimationFrame(() => requestAnimationFrame(() => r())));
    this.stage?.flush();
    const s = this.controller.snapshot();
    return { segments: s.segments.map((x) => ({ from: [...x.from], to: [...x.to], color: x.color, width: x.width })) as RunResult["segments"], error: s.error };
  }

  /* ------------------------------------------------------------ execution controls */

  doRun() {
    this.autoFit = true;
    this.budget = 0;
    this.controller.run();
    if (SPEEDS[this.speed] === Infinity) this.controller.advance(Infinity);
    this.ensureLoop();
  }

  doStep() {
    this.controller.step();
  }

  doPause() {
    const s = this.controller.snapshot().state;
    if (s === "running") this.controller.pause();
    else if (s === "paused") {
      this.controller.resume();
      this.ensureLoop();
    }
  }

  doReset() {
    this.controller.reset();
    this.autoFit = true;
    this.stage?.resetView();
    this.lastError = null;
  }

  private setSpeed(i: number) {
    this.speed = i;
    this.speedOut.textContent = SPEED_LABELS[i];
    if (SPEEDS[i] === Infinity && this.controller.snapshot().state === "running") this.controller.advance(Infinity);
  }

  private ensureLoop() {
    if (this.looping) return;
    this.looping = true;
    this.lastFrame = performance.now();
    const frame = (now: number) => {
      const s = this.controller.snapshot();
      if (s.state !== "running") {
        this.looping = false;
        return;
      }
      const rate = SPEEDS[this.speed];
      const dt = Math.min(100, now - this.lastFrame);
      this.lastFrame = now;
      if (rate === Infinity) this.controller.advance(Infinity);
      else {
        this.budget += (rate * dt) / 1000;
        const n = Math.floor(this.budget);
        if (n > 0) {
          this.budget -= n;
          this.controller.advance(n);
        }
      }
      requestAnimationFrame(frame);
    };
    requestAnimationFrame(frame);
  }

  /** Called on every keyboard shortcut press; returns true when the key was handled. */
  handleShortcut(e: KeyboardEvent): boolean {
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key === "Enter") this.doRun();
    else if (e.altKey && !mod && e.code === "KeyR") this.doRun();
    else if (e.altKey && !mod && e.code === "KeyK") this.doStep();
    else if (e.altKey && !mod && e.code === "KeyP") this.doPause();
    else if (e.altKey && !mod && e.code === "KeyZ") this.doReset();
