type Theme = "auto" | "light" | "dark";
const THEME_LABEL: Record<Theme, string> = { auto: "automatyczny", light: "jasny", dark: "ciemny" };

function storage(): Storage | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export class App {
  private drafts: DraftStore;
  private progress: ProgressStore;
  private toasts: Toasts;
  readonly workspace: Workspace;
  private main = h("main", { id: "main" });
  private page = h("div", { class: "page-host" });
  private themeBtn!: HTMLButtonElement;
  private navLinks = new Map<string, HTMLAnchorElement>();
  private theme: Theme = "auto";
  private firstRoute = true;
  private heading = h("h1", { class: "sr-only", tabindex: "-1" }, "Pracownia");

  constructor(private root: HTMLElement) {
    const kv = storage();
    this.drafts = new DraftStore(kv);
    this.progress = new ProgressStore(kv);
    this.toasts = new Toasts();
    this.theme = ((): Theme => {
      try {
        const t = kv?.getItem("logomocja.theme");
        return t === "light" || t === "dark" ? t : "auto";
      } catch {
        return "auto";
      }
    })();
    this.workspace = new Workspace({ drafts: this.drafts, progress: this.progress, toasts: this.toasts });
    this.build();
    this.applyTheme();
    window.addEventListener("hashchange", () => void this.route());
    document.addEventListener("keydown", (e) => {
      if (this.isWorkspaceVisible() && !document.querySelector("dialog[open]")) this.workspace.handleShortcut(e);
    });
  }

  private isWorkspaceVisible() {
    return !this.workspace.el.hidden;
  }

  private build() {
    const link = (key: string, href: string, text: string) => {
      const a = h("a", { href }, text);
      this.navLinks.set(key, a);
      return a;
    };
    this.themeBtn = h("button", { type: "button", class: "btn icon-only", on: { click: () => this.cycleTheme() } });
    const header = h("header", { class: "topbar" },
      h("a", { class: "brand", href: "#/pracownia" }, icon("turtle"), h("span", null, "Logomocja")),
      h("nav", { "aria-label": "Główna" }, link("pracownia", "#/pracownia", "Pracownia"), link("wyzwania", "#/wyzwania", "Wyzwania"), link("pomoc", "#/pomoc", "Polecenia")),
      h("span", { class: "grow" }),
      h("button", { type: "button", class: "btn icon-only", title: "Skróty klawiszowe", "aria-label": "Skróty klawiszowe", on: { click: () => void showShortcuts() } }, icon("keyboard")),
      this.themeBtn,
    );
    this.workspace.el.hidden = true;
    this.main.append(this.heading, this.workspace.el, this.page);
    this.root.replaceChildren(
      h("a", { class: "skip", href: "#main", on: { click: (e: Event) => { e.preventDefault(); this.main.focus(); } } }, "Przejdź do treści"),
      header,
      this.main,
    );
    this.main.tabIndex = -1;
  }

  /* ---------------------------------------------------------------- theme */

  private cycleTheme() {
    this.theme = this.theme === "auto" ? "light" : this.theme === "light" ? "dark" : "auto";
    try {
      storage()?.setItem("logomocja.theme", this.theme);
    } catch {
      /* ignore */
    }
    this.applyTheme();
  }

  private applyTheme() {
    const root = document.documentElement;
    if (this.theme === "auto") root.removeAttribute("data-theme");
    else root.setAttribute("data-theme", this.theme);
    this.themeBtn.replaceChildren(icon(this.theme === "auto" ? "auto" : this.theme === "light" ? "sun" : "moon"));
    const label = `Motyw: ${THEME_LABEL[this.theme]}. Zmień motyw`;
    this.themeBtn.setAttribute("aria-label", label);
    this.themeBtn.title = label;
  }

  /* ---------------------------------------------------------------- routing */

  async start() {
    await this.route();
  }

  private async route() {
    const shared = decodePermalink(location.hash);
    if (shared) {
      this.show("pracownia");
      history.replaceState(null, "", "#/pracownia");
      await this.workspace.loadShared(shared.source, shared.mode);
      this.toasts.show("Wczytano i uruchomiono program z linku.");
      return;
    }
    const path = location.hash.replace(/^#/, "").split("?")[0].replace(/\/+$/, "");
    const [, section = "", id = ""] = path.split("/");
    if (section === "wyzwania" && id) {
      if (challengeById(id)) {
        this.workspace.enter({ kind: "challenge", id });
        this.show("pracownia", `Wyzwanie: ${challengeById(id)!.title}`);
      } else location.hash = "#/wyzwania";
    } else if (section === "wyzwania") {
      this.show("wyzwania");
    } else if (section === "pomoc") {
      this.show("pomoc");
    } else {
      this.workspace.enter({ kind: "free" });
      this.show("pracownia");
    }
  }

  /** Makes one view visible; the workspace is kept alive between visits so nothing is lost. */
  show(view: "pracownia" | "wyzwania" | "pomoc", title?: string) {
    (this.page as any)._destroy?.();
    const prev = this.page.firstElementChild as any;
    prev?._destroy?.();
    this.page.replaceChildren();
    const isWork = view === "pracownia";
    this.workspace.el.hidden = !isWork;
    this.heading.hidden = !isWork;
    this.heading.textContent = title ?? "Pracownia";
    if (view === "wyzwania") this.page.append(renderChallengesPage(this.progress, () => this.show("wyzwania")));
    if (view === "pomoc") {
      this.page.append(renderReferencePage((source, mode) => {
        void this.workspace.adopt(source, mode, { confirm: true, what: "przykład z opisu" }).then((ok) => {
          if (ok) {
            location.hash = "#/pracownia";
            this.workspace.focusEditor();
          }
        });
      }));
    }
    const names: Record<string, string> = { pracownia: "Pracownia", wyzwania: "Wyzwania", pomoc: "Polecenia" };
    document.title = `${title ?? names[view]} — Logomocja`;
    const active = this.workspace.context.kind === "challenge" && isWork ? "wyzwania" : view;
    this.navLinks.forEach((a, k) => (k === active ? a.setAttribute("aria-current", "page") : a.removeAttribute("aria-current")));
    if (isWork) this.workspace.shown();
    if (!this.firstRoute) {
      const target = isWork ? this.heading : (this.page.querySelector("h1") as HTMLElement);
      target?.focus({ preventScroll: false });
      window.scrollTo(0, 0);
    }
    this.firstRoute = false;
  }

  /* ---------------------------------------------------------------- testing hooks */

  async open(source: string, mode: Mode): Promise<RunResult> {
    const m: Mode = mode === "3d" ? "3d" : "2d";
    if (location.hash !== "#/pracownia") history.replaceState(null, "", "#/pracownia");
    this.workspace.enter({ kind: "free" });
    this.show("pracownia");
    await new Promise<void>((r) => requestAnimationFrame(() => r()));
    return this.workspace.openProgram(String(source), m);
  }
}

export function installHook(app: App | null) {
  (window as any).logomocja = {
    version: VERSION,
    run: (source: string, mode: Mode): RunResult => run(String(source), mode === "3d" ? "3d" : "2d"),
    open: (source: string, mode: Mode): Promise<RunResult> => (app ? app.open(source, mode) : Promise.resolve(run(String(source), mode === "3d" ? "3d" : "2d"))),
  };
}

export { EXAMPLES };
