.ref-entry p { margin: .3rem 0; }
.aliases code, .syntax code, .ref-entry p code { background: var(--panel-2); border: 1px solid var(--line); border-radius: 5px; padding: 0 .35rem; font-size: .9em; }
.codeblock { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: .6rem .8rem; overflow: auto; margin: .5rem 0; font-size: .9rem; line-height: 1.5; }
.kbd-table { border-collapse: collapse; width: 100%; }
.kbd-table caption { text-align: left; font-weight: 700; padding-bottom: .4rem; }
.kbd-table th, .kbd-table td { text-align: left; padding: .4rem .6rem; border-bottom: 1px solid var(--line); vertical-align: top; }
kbd { background: var(--panel-2); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 5px; padding: 0 .35rem; font-size: .85em; }

/* ---------- dialog and toasts ---------- */
.dialog { border: 1px solid var(--line); border-radius: 14px; background: var(--panel); color: var(--ink); padding: 1.2rem; width: min(92vw, 560px); box-shadow: 0 20px 60px rgba(0, 0, 0, .35); max-height: 90dvh; overflow: auto; }
.dialog.wide { width: min(94vw, 960px); }
.dialog::backdrop { background: rgba(8, 14, 12, .55); }
.dialog h2 { font-size: 1.3rem; }
.dialog-actions { display: flex; justify-content: flex-end; gap: .5rem; margin-top: 1rem; flex-wrap: wrap; }
.share-input { width: 100%; padding: .5rem; font: inherit; font-family: ui-monospace, monospace; border: 1px solid var(--line); border-radius: 8px; background: var(--panel-2); color: var(--ink); }
.toasts { position: fixed; left: 50%; bottom: 1rem; transform: translateX(-50%); display: grid; gap: .5rem; z-index: 100; width: min(92vw, 520px); pointer-events: none; }
.toast { pointer-events: auto; display: flex; align-items: center; justify-content: space-between; gap: .75rem; background: var(--ink); color: var(--bg); padding: .6rem .9rem; border-radius: 10px; box-shadow: 0 8px 24px rgba(0, 0, 0, .3); }
.toast .btn { background: transparent; color: inherit; border-color: currentColor; }

/* ---------- small screens ---------- */
@media (max-width: 900px) {
  .workspace { grid-template-columns: minmax(0, 1fr); height: auto; padding: .6rem; }
  .editor { flex: none; height: 300px; }
  .stage-wrap { flex: none; height: min(70vh, 520px); min-height: 300px; }
  .speed { margin-left: 0; width: 100%; }
  .speed input { flex: 1; width: auto; }
  .task-body { grid-template-columns: 1fr; }
  canvas.preview { height: 170px; }
  .ref-layout { grid-template-columns: 1fr; }
  .toc { position: static; }
  .topbar { padding: .4rem .6rem; }
  .btn .label { font-size: .9rem; }
}
@media (max-width: 480px) {
  .toolbar.secondary .btn .label { display: none; }
  .toolbar.secondary .btn { width: 44px; padding: 0; }
  .toolbar.secondary .btn.wide-label { width: auto; }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
@media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }
