cat >> test/interpreter.test.ts <<'EOF'

describe("robustness", () => {
  test("very deeply nested parentheses are evaluated, not a crash", () => {
    const n = 3000;
    const r = run(`np ${"(".repeat(n)}1${")".repeat(n)}`, "2d");
    expect(r.error).toBeNull();
    expect(r.segments[0].to).toEqual([0, 1, 0]);
  });
  test("very long operator chains are evaluated", () => {
    const r = run(`np ${"1+".repeat(3000)}1`, "2d");
    expect(r.error).toBeNull();
    expect(r.segments[0].to[1]).toBe(3001);
  });
  test("a long chain of unary signs is evaluated", () => {
    expect(run(`np ${"-".repeat(3001)}2`, "2d").segments[0].to[1]).toBe(-2);
  });
  test("unclosed parentheses are reported at the innermost unmatched one", () => {
    expect(run("np ((1 + 2)", "2d").error).toMatchObject({ line: 1, column: 4 });
    expect(run("np (1 + (2", "2d").error).toMatchObject({ line: 1, column: 9 });
  });
  test("a stray closing parenthesis is an error at itself", () => {
    expect(run("np (1))", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("decomposed (combining) accents are accepted in names", () => {
    const decomposed = "kąt".normalize("NFD"); // k a + combining ogonek + t
    expect(run(`niech ${decomposed} 5 np kąt`, "2d").error).toBeNull();
  });
});
EOF
