      } else if (this.isBinary(t) && "+-*/".includes(t.text)) {
        this.i++;
        const prec = t.text === "+" || t.text === "-" ? 1 : 2;
        flushTo(prec);
        stack.push({ t: "bin", op: t.text as "+" | "-" | "*" | "/", prec });
        expectOperand = true;
        missing = `Brakuje wartości po „${t.text}”.`;
        last = t;
      } else if (t && t.kind === "rpar" && stack.some((s) => s.t === "paren")) {
        this.i++;
        flushTo(0);
        stack.pop();
      } else break;
    }
    const open = [...stack].reverse().find((s) => s.t === "paren");
    if (open && open.t === "paren") this.fail("Brakuje zamykającego nawiasu „)”.", open.tok);
    flushTo(0);
  }

  private declared(name: string): boolean {
    if (this.scope && (this.scope.params.includes(name) || this.scope.locals.has(name))) return true;
    return this.globals.has(name);
  }

  /** Consumes nrpowt or a variable/parameter name if `t` is one; returns false if `t` cannot be an operand. */
  private operandWord(t: Token, out: RpnOp[]): boolean {
    if (t.kind === "word" && (t.text === "nrpowt" || t.text === "repcount")) {
      if (this.repDepth === 0) this.fail("„nrpowt” można użyć tylko wewnątrz powtórzenia.", t);
      this.i++;
      out.push({ k: "rep" });
      return true;
    }
    if ((t.kind === "word" && !RESERVED.has(t.text)) || t.kind === "colon") {
      if (!this.declared(t.text)) this.fail(`Nieznana nazwa „${t.text}” — to nie jest ani parametr, ani zmienna.`, t);
      this.i++;
      out.push({ k: "var", name: t.text });
      return true;
    }
    return false;
  }
}
